    "type": "mcq",
    "q": "เมื่อแยกวิเคราะห์ตามกลุ่มย่อยแล้วพบว่าผลของปัจจัยต่อการเกิดโรคมีขนาดต่างกันในแต่ละกลุ่ม เช่น ประสิทธิผลของวัคซีนต่างกันตามอายุ ตัวแปรที่สามนี้คืออะไร และควรจัดการอย่างไร",
    "options": [
      "Confounding factor ควรปรับค่า (adjust) แล้วรายงานค่าที่ปรับแล้วค่าเดียว",
      "Interaction (effect modification) ควรรายงานผลแยกตามกลุ่มย่อย ไม่ปรับทิ้ง",
      "Selection bias ควรเก็บตัวอย่างใหม่ให้เป็นตัวแทนของประชากรต้นทาง",
      "Mediator บน causal pathway ควรปรับค่าออกเพื่อให้เห็นผลที่แท้จริง"
    ],
    "answer": 1,
    "explain": "Interaction หรือ effect modification คือกรณีที่ผลของปัจจัยต่อโรคต่างกันระหว่างกลุ่มย่อยของตัวแปรที่สาม เช่น ประสิทธิผลของวัคซีนต่างกันตามอายุ หรือผลของ heat stress ต่อการผสมติดต่างกันตามระดับการให้นม ปรากฏการณ์นี้ไม่ใช่ความผิดพลาดหรือ bias แต่เป็นความจริงทางชีววิทยา จึงต้องรายงานค่าแยกตามชั้น (stratum-specific estimates) และทดสอบ interaction term ไม่ปรับทิ้ง ต่างจาก confounding ที่ตัวแปรที่สามสัมพันธ์กับทั้งปัจจัยและโรคจนบิดเบือนผล ซึ่งต้องปรับค่าแล้วรายงานค่าที่ปรับแล้ว ส่วน mediator ที่อยู่บน causal pathway ไม่ควรปรับค่าออก เพราะจะลบผลรวมของปัจจัยนั้นไป",
