    "explain": "Group 1 คือโรคที่ก่อความสูญเสียหรือความเสียหายรุนแรงและต้องถือเป็นกรณีฉุกเฉินเมื่อเกิดขึ้น ได้แก่ foot and mouth disease, haemorrhagic septicaemia, anthrax, blackleg, classical swine fever, Newcastle disease, brucellosis และ tuberculosis กำหนดให้รายงานทุกครั้งที่เกิดโรค โดยสำนักงานปศุสัตว์จังหวัด ด่านกักกันสัตว์ และศูนย์หรือสถานีบำรุงพันธุ์สัตว์ การรายงานทุกครั้งที่สงสัยเป็นเกณฑ์ของ Group 2 (exotic diseases) การรายงานหลังยืนยันผลจากห้องปฏิบัติการโดยสำนักงานปศุสัตว์จังหวัดเป็นเกณฑ์ของ Group 3 และการรายงานรายเดือนโดยสถาบันสุขภาพสัตว์แห่งชาติกับศูนย์วิจัยและพัฒนาการสัตวแพทย์ภูมิภาคเป็นเกณฑ์ของ Group 4",
