    "explain": "ข้อแรกเป็นการบรรยายว่าโรคเกิดกับสัตว์กลุ่มใด ที่ไหน และเมื่อไร ซึ่งเป็นส่วนของระบาดวิทยาเชิงพรรณนา สองข้อถัดมาเป็นการหาปัจจัยเสี่ยง สาเหตุของโรค และองค์ประกอบที่ทำให้เกิดการระบาด และข้อสุดท้ายนำความรู้ทั้งหมดไปสู่แนวทางป้องกันและควบคุมโรค การรักษาสัตว์ป่วยเป็นรายตัวไม่อยู่ในจุดมุ่งหมายนี้ เพราะเป็นวัตถุประสงค์ของคลินิกอายุรกรรม",
