    "model_answer": "ระบาดวิทยาช่วยค้นหาสาเหตุของปัญหาทางสุขภาพ (causation) แหล่งรังโรค (source of infection) องค์ประกอบที่เสี่ยงต่อการเกิดโรค (risk factor) รวมถึงโรคอุบัติใหม่ (emerging disease) โรคอุบัติซ้ำ (re-emerging disease) และโรคที่ยังไม่ทราบสาเหตุ (unknown-caused disease) ในการระบาด ระบาดวิทยาช่วยสอบสวนสาเหตุของการระบาด รวมทั้งแหล่งและวิธีการแพร่เชื้อ และช่วยอธิบายธรรมชาติของการเกิดโรค (natural history of disease) ทั้งลักษณะอาการ ลักษณะการเกิดโรค การกระจายของโรคตามชนิดสัตว์ เวลา และสถานที่ และกลุ่มสัตว์ที่เสี่ยงต่อโรค",
