    "q": "องค์ประกอบในการศึกษาระบาดวิทยาทางสัตวแพทย์ ตั้งแต่การสืบค้นการระบาดและการรวบรวมข้อมูล มุ่งไปสู่ปลายทางใด",
    "options": [
      "การป้องกันและควบคุมโรค",
      "การทดสอบสมมติฐานการเกิดโรค",
      "การประเมินค่าทางเศรษฐกิจ",
      "การศึกษาเชิงทดลอง"
    ],
    "answer": 0,
    "explain": "องค์ประกอบในการศึกษาระบาดวิทยาทางสัตวแพทย์เรียงจากการสืบค้นการระบาด การรวบรวมข้อมูล การประเมินข้อมูลเชิงคุณภาพจากธรรมชาติการเกิดโรค การประเมินข้อมูลเชิงปริมาณ การศึกษาทางระบาดวิทยาทั้งเชิงสังเกตและเชิงทดลอง การทดสอบสมมติฐาน และการประเมินค่าทางเศรษฐกิจ ทุกขั้นนำไปสู่การป้องกันและควบคุมโรคซึ่งเป็นปลายทาง เป้าหมายของการศึกษาทางระบาดวิทยาคือเสริมความรู้ของสัตวแพทย์เพื่อการควบคุมโรคที่มีประสิทธิภาพ การทดสอบสมมติฐานและการประเมินค่าทางเศรษฐกิจเป็นขั้นก่อนปลายทาง ส่วนการศึกษาเชิงทดลองเป็นรูปแบบหนึ่งของการศึกษาทางระบาดวิทยาที่อยู่กลางทาง",
