    "q": "พยาธิ Haemonchus contortus ทำให้เกิดทั้ง abomasal hyperplasia และภาวะโลหิตจาง (anemia) หากพบว่า abomasal hyperplasia กับภาวะโลหิตจางเกิดร่วมกันบ่อย ความสัมพันธ์ระหว่างสองภาวะนี้เป็นแบบใด",
    "options": [
      "Direct association แบบ one-to-one เพราะ abomasal hyperplasia ทำให้เกิดภาวะโลหิตจาง",
      "Indirect association ที่ไม่ใช่เหตุและผล เพราะทั้งสองภาวะมีสาเหตุร่วมคือพยาธิตัวเดียวกัน",
      "Spurious association ที่เกิดจากความบังเอิญหรือ bias ในการเก็บข้อมูลเท่านั้น",
      "Multifactorial causation เพราะพยาธิและ abomasal hyperplasia ร่วมกันก่อภาวะโลหิตจาง"
    ],
    "answer": 1,
    "explain": "Haemonchus contortus เป็นสาเหตุของทั้ง abomasal hyperplasia และภาวะโลหิตจาง สองภาวะนี้จึงพบร่วมกันบ่อยโดยที่ภาวะหนึ่งไม่ได้เป็นสาเหตุของอีกภาวะ จัดเป็น indirect association คือความสัมพันธ์ทางสถิติที่ไม่ใช่เหตุและผล เกิดเพราะมีตัวแปรที่สามซึ่งสัมพันธ์กับทั้งสองภาวะ ในที่นี้คือพยาธิ ซึ่งทำหน้าที่เป็น confounding factor ถ้ามอง abomasal hyperplasia เป็นปัจจัยที่สงสัยของภาวะโลหิตจาง ส่วนพยาธิเองมีความสัมพันธ์เชิงสาเหตุกับทั้งสองภาวะ spurious association เกิดจากความบังเอิญหรือ bias ไม่ใช่จากสาเหตุร่วม และการบอกว่า abomasal hyperplasia ทำให้เกิดภาวะโลหิตจางคือการอ่านความสัมพันธ์แบบนี้ผิดเป็นเหตุและผล",
