    "id": 214535,
    "subject": "epidemiology",
    "topic": "epidem-causation",
    "year": 5,
    "type": "mcq",
    "q": "จากตาราง ถ้าคำนวณโดยตั้งต้นจากสถานะโรคแทน คือ [a/(a+c)] ÷ [b/(b+d)] และ (a/c) ÷ (b/d) ข้อใดถูกต้อง",
    "say": "กำหนดข้อมูล 2x2 ดังนี้ สัมผัสปัจจัย: เป็นโรค a ไม่เป็นโรค b; ไม่สัมผัสปัจจัย: เป็นโรค c ไม่เป็นโรค d ถ้าคำนวณโดยตั้งต้นจากสถานะโรคแทน คือ [a/(a+c)] ÷ [b/(b+d)] และ (a/c) ÷ (b/d) ข้อใดถูกต้อง",
    "passage": "กำหนดข้อมูล 2x2 ดังนี้\n\n| | เป็นโรค | ไม่เป็นโรค |\n|---|---|---|\n| สัมผัสปัจจัย | a | b |\n| ไม่สัมผัสปัจจัย | c | d |",
    "passage_title": "การสัมผัสปัจจัยกับการเป็นโรค",
    "options": [
      "ค่าแรกไม่เท่ากับ RR = [a/(a+b)] ÷ [c/(c+d)] แต่ค่าที่สองเท่ากับ OR = ad/bc",
      "ค่าแรกเท่ากับ RR = [a/(a+b)] ÷ [c/(c+d)] แต่ค่าที่สองไม่เท่ากับ OR = ad/bc",
      "ทั้งสองค่าเท่ากับ RR และ OR ที่คำนวณตามแถวการสัมผัสปัจจัยตามลำดับ",
      "ทั้งสองค่าไม่เท่ากับ RR และ OR ที่คำนวณตามแถวการสัมผัสปัจจัยตามลำดับ"
    ],
    "answer": 0,
    "explain": "RR ต้องคิดจากความเสี่ยงของโรคในแต่ละกลุ่มการสัมผัส คือ [a/(a+b)] ÷ [c/(c+d)] ถ้าตั้งต้นจากสถานะโรคเป็น [a/(a+c)] ÷ [b/(b+d)] จะได้การเปรียบเทียบการสัมผัสปัจจัยระหว่างกลุ่มป่วยกับกลุ่มไม่ป่วย ซึ่งไม่เท่ากับ RR การวางข้อมูล 2x2 ให้แถวเป็นการสัมผัสและคอลัมน์เป็นโรคจึงสำคัญเมื่อคำนวณ RR ส่วน OR ได้ค่าเดียวกันทั้งสองทาง เพราะ odds ของการเป็นโรค (a/b) ÷ (c/d) และ odds ของการสัมผัส (a/c) ÷ (b/d) ต่างก็เท่ากับ ad/bc",
    "source": "Measurement of disease frequency- measurement of association- diagnostic test หน้า 54, 60-62",
    "verified": "สไลด์ Association vs Causation ชุดปี 2567 หน้า 30 (RR ไฮไลต์หัวแถวและหัวคอลัมน์ของตาราง 2x2, ผลรวม a กับ b และผลรวม c กับ d พร้อมดาวและหมึกแดงเตือนให้เรียงตารางให้ถูก) และหน้า 32 (OR ไฮไลต์ c/d และ bc) ในชุดไฟล์ของ Vet 84 (หน้ากระดาษไม่ระบุรุ่น)",
