    "id": 214539,
    "subject": "epidemiology",
    "topic": "epidem-disease-frequency",
    "year": 5,
    "type": "mcq",
    "q": "ค่าใดต่อไปนี้มีเวลาที่สัตว์แต่ละตัวอยู่ในภาวะเสี่ยงเป็นส่วนหนึ่งของตัวหาร จึงจัดเป็นอัตรา (rate) ที่บอกความเร็วของการเกิดโรค",
    "options": [
      "Incidence rate ต่อ animal-year",
      "Attack rate ในการระบาด",
      "Case fatality rate ของโรค",
      "Cumulative incidence ใน 1 ปี"
    ],
    "answer": 0,
    "explain": "อัตรา (rate) ต่างจากสัดส่วนตรงที่นำเวลามาคิดด้วย incidence rate หารจำนวนสัตว์ป่วยใหม่ด้วยผลรวมเวลาที่สัตว์แต่ละตัวอยู่ในภาวะเสี่ยง หน่วยจึงเป็นต่อ animal-month หรือต่อ animal-year และบอกว่าโรคเกิดเร็วเพียงใด ค่าอื่นแม้ชื่อจะมีคำว่า rate หรือ incidence ก็ไม่มีเวลาในตัวหาร attack rate คือจำนวนที่ป่วยในการระบาดหารด้วยจำนวนที่เสี่ยงต่อโรค case fatality rate คือจำนวนที่ตายด้วยโรคหารด้วยจำนวนที่ป่วยด้วยโรคนั้น และ cumulative incidence คือจำนวนป่วยใหม่หารด้วยจำนวนสัตว์ในประชากรเสี่ยงเมื่อเริ่มต้น ซึ่งไม่คิดเวลาของแต่ละตัว ช่วง 1 ปีจึงเป็นเพียงกรอบเวลาของการนับ ไม่ได้อยู่ในตัวหาร",
    "source": "Measurement of disease frequency- measurement of association- diagnostic test หน้า 12-19, 31, 36, 47; Data analysis & applied statistic for epidemiology_TC หน้า 137, 139-140; 5_vet_epidem_dis_frequency_070824 deck 2024 หน้า 4-5, 8",
