    "q": "อาหารโคปนเปื้อนสารพิษจากเชื้อรา ทำให้โคเสี่ยงต่อโรคเพียงช่วงสั้น ๆ ระหว่างการระบาด ค่าใดเหมาะใช้บรรยายสัดส่วนของโคที่ป่วยแทนอัตราอุบัติการณ์",
