    "explain": "Attack rate ใช้ในสถานการณ์การระบาด คือจำนวนสัตว์ที่ป่วยหารด้วยจำนวนสัตว์ที่เสี่ยงต่อโรค นำมาใช้แทนอัตราอุบัติการณ์เมื่อประชากรเสี่ยงต่อโรคเพียงช่วงสั้น เช่น อาหารปนเปื้อนสารพิษจากเชื้อรา ซึ่งแม้เฝ้าสังเกตต่อไปนานเท่าใดอุบัติการณ์ก็ไม่เปลี่ยน ค่านี้จึงบรรยายสัดส่วนของสัตว์ที่เกิดโรค ส่วน incidence rate ต้องรวมเวลาเสี่ยงของแต่ละตัวเพื่อบอกความเร็วของการเกิดโรค point prevalence นับสัตว์ป่วยที่มีอยู่ ณ วันเดียวทั้งรายเก่าและรายใหม่ และ case fatality rate นับเฉพาะตัวที่ตายในกลุ่มที่ป่วย",
