    "q": "การหาอุบัติการณ์ของมะเร็งเต้านมในแมวใช้ประชากรแมวเพศเมียเป็นตัวหาร แต่การหาอุบัติการณ์ของโรคไข้หัดแมวใช้ประชากรแมวทั้งหมดของพื้นที่ในช่วงเวลาที่กำหนด หลักใดทำให้ตัวหารของสองโรคต่างกัน",
