    "id": 214553,
    "subject": "epidemiology",
    "topic": "epidem-dx-screening",
    "year": 5,
    "type": "mcq",
    "q": "เมื่อจัดผลชุดตรวจเทียบกับ gold standard เป็นตาราง 2x2 โดยแถวบนคือผลบวก (a = ผลบวกจริง, b = ผลบวกลวง) และแถวล่างคือผลลบ (c = ผลลบลวง, d = ผลลบจริง) ผลรวม a + b หมายถึงอะไร และใช้เป็นตัวหารของค่าใด",
    "options": [
      "สัตว์ที่เป็นโรคจริงทั้งหมด ใช้เป็นตัวหารของ sensitivity",
      "สัตว์ที่ผลตรวจเป็นบวกทั้งหมด ใช้เป็นตัวหารของ PPV",
      "สัตว์ที่ผลตรวจเป็นลบทั้งหมด ใช้เป็นตัวหารของ NPV",
      "สัตว์ที่ไม่เป็นโรคทั้งหมด ใช้เป็นตัวหารของ specificity"
    ],
    "answer": 1,
    "explain": "แถวบนรวมสัตว์ทุกตัวที่ชุดตรวจให้ผลบวก ทั้งที่เป็นโรคจริง (a) และไม่เป็นโรค (b) ผลรวม a + b จึงเป็นตัวหารของ positive predictive value ซึ่งถามว่าสัตว์ที่ผลบวกเป็นโรคจริงกี่ส่วน PPV = a/(a + b) เช่น ผลบวก 150 ตัวเป็นโรคจริง 90 ตัว ได้ PPV = 90/150 = 60% ตัวหารของ sensitivity คือสัตว์ที่เป็นโรคจริงทั้งหมด a + c ซึ่งรวมตามสถานะโรค ไม่ใช่ตามผลตรวจ และผลรวมแถวล่าง c + d เป็นตัวหารของ NPV",
    "source": "Measurement of disease frequency- measurement of association- diagnostic test หน้า 84-89; 7_vet_epidem_Dx_and_Screening_070824 deck 2024 หน้า 18-20",
    "verified": "สไลด์ Screening and Diagnostic tests ชุดปี 2567 (7_vet_epidem_Dx_and_Screening_070824) หน้า 18 มาร์คในสำเนาจากโฟลเดอร์ของ Vet 84 (รุ่นอนุมานจากโฟลเดอร์ ไม่ได้ระบุบนหน้า)",
