    "type": "mcq",
    "q": "ข้อใดถูกต้องเกี่ยวกับการจำแนกรูปแบบการศึกษาทางระบาดวิทยา",
    "options": [
      "Experimental study ผู้วิจัยเพียงสังเกต exposure ที่เกิดขึ้นเอง โดยไม่ได้กำหนดสิ่งแทรกแซงใด",
      "Cross-sectional study เป็นการศึกษาเชิงทดลอง เพราะวัด exposure และโรคในเวลาเดียวกัน",
      "Descriptive study ใช้ทดสอบสมมติฐานเรื่องปัจจัยเสี่ยง โดยเทียบกับกลุ่มที่ไม่ได้สัมผัสปัจจัย",
      "Cohort และ case-control เป็นการศึกษาเชิงสังเกตแบบวิเคราะห์ ที่มีกลุ่มเปรียบเทียบเพื่อทดสอบสมมติฐาน"
    ],
    "answer": 3,
    "explain": "การศึกษาแบ่งเป็นเชิงทดลอง (experimental) ซึ่งผู้วิจัยกำหนด exposure หรือสิ่งแทรกแซงเอง เช่น randomized trial กับเชิงสังเกต (observational) ซึ่งผู้วิจัยสังเกต exposure ที่เกิดขึ้นจริงโดยไม่กำหนด การศึกษาเชิงสังเกตแบ่งต่อเป็นเชิงพรรณนา ที่บรรยายการเกิดโรค เช่น prevalence และ incidence โดยไม่มีกลุ่มเปรียบเทียบ และใช้ตั้งสมมติฐาน กับเชิงวิเคราะห์ ที่มีกลุ่มเปรียบเทียบเพื่อทดสอบสมมติฐานว่าปัจจัยใดสัมพันธ์กับโรค ได้แก่ cohort, case-control และ cross-sectional การวัด exposure กับโรคในเวลาเดียวกันเป็นลักษณะของ cross-sectional ซึ่งยังเป็นการศึกษาเชิงสังเกต เพราะผู้วิจัยไม่ได้กำหนด exposure",
