    "id": 214572,
    "subject": "epidemiology",
    "topic": "epidem-observational-study",
    "year": 5,
    "type": "mcq",
    "q": "จากตาราง odds ratio คำนวณจากข้อใด",
    "say": "Case-control study สุ่ม case 12 ราย พบว่าเคยสัมผัสปัจจัย 8 ราย ไม่เคย 4 ราย และสุ่ม control 36 ราย พบว่าเคยสัมผัสปัจจัย 5 ราย ไม่เคย 31 ราย odds ratio คำนวณจากข้อใด",
    "passage": "Case-control study สุ่ม case 12 ราย และสุ่ม control 36 ราย ตารางแสดงจำนวนราย\n\n| | เคยสัมผัสปัจจัย | ไม่เคย | รวม |\n|---|---|---|---|\n| Case | 8 | 4 | 12 |\n| Control | 5 | 31 | 36 |",
    "passage_title": "การสัมผัสปัจจัยใน case และ control",
    "options": [
      "(8/12)/(5/36)",
      "(5/31)/(8/4)",
      "(8 x 31)/(4 x 5)",
      "(8 x 5)/(4 x 31)"
    ],
    "answer": 2,
    "explain": "Case-control study เลือกตัวอย่างจากสถานะโรค จึงเทียบ odds ของการสัมผัสปัจจัยระหว่างกลุ่ม case กับ control\n**odds ของ case** 8/4 = 2.0\n**odds ของ control** 5/31 = 0.16\n**odds ratio** คือ odds ของ case หารด้วย odds ของ control ซึ่งเท่ากับผลคูณไขว้ ad/bc = (8 x 31)/(4 x 5)\n**แปลผล** ได้ค่ามากกว่า 1 แปลว่าการสัมผัสปัจจัยสัมพันธ์กับการเป็นโรค\n\n**ข้อควรระวัง**\n— การหารสัดส่วนที่สัมผัส (8/12 กับ 5/36) ไม่ใช่ odds\n— การเอา odds ของ control เป็นตัวตั้งทำให้ได้ค่ากลับด้าน",
    "explainSay": "Case-control study เลือกตัวอย่างจากสถานะโรค จึงเทียบ odds ของการสัมผัสปัจจัยระหว่างกลุ่ม case กับ control odds ของ case คือ 8/4 = 2.0 และของ control คือ 5/31 = 0.16 odds ratio คือ odds ของ case หารด้วย odds ของ control ซึ่งเท่ากับผลคูณไขว้ ad/bc = (8 x 31)/(4 x 5) ได้ค่ามากกว่า 1 แปลว่าการสัมผัสปัจจัยสัมพันธ์กับการเป็นโรค การหารสัดส่วนที่สัมผัส (8/12 กับ 5/36) ไม่ใช่ odds และการเอา odds ของ control เป็นตัวตั้งทำให้ได้ค่ากลับด้าน",
    "source": "Study Design หน้า 19-24, 27; Measurement of disease frequency- measurement of association- diagnostic test หน้า 59-62; Data analysis & applied statistic for epidemiology_TC หน้า 146; 8 - Observational_study_2567 deck 2024 หน้า 27, 29",
