    "type": "mcq",
    "q": "ศึกษาเต้านมอักเสบหลังคลอดในโค โคที่คลอดนอกซองคลอด 59 ตัวเป็นเต้านมอักเสบ 23 ตัว ส่วนโคที่คลอดในซองคลอด 27 ตัวเป็น 1 ตัว ถ้าการคลอดนอกซองคลอดคือปัจจัยที่สัมผัส relative risk คำนวณจากข้อใด",
    "options": [
      "(23/36)/(1/26)",
      "(23/24)/(36/62)",
      "(23/59) - (1/27)",
      "(23/59)/(1/27)"
    ],
    "answer": 3,
    "explain": "Relative risk เทียบความเสี่ยงของการเกิดโรคในกลุ่มที่สัมผัสปัจจัยกับกลุ่มที่ไม่สัมผัส ความเสี่ยงคือจำนวนที่ป่วยหารด้วยจำนวนทั้งหมดของกลุ่ม คลอดนอกซองคลอด 23/59 หรือประมาณ 0.39 และคลอดในซองคลอด 1/27 หรือประมาณ 0.04 RR = (23/59)/(1/27) ซึ่งมากกว่า 1 มาก แปลว่าการคลอดนอกซองคลอดเพิ่มความเสี่ยงเต้านมอักเสบ ส่วน (23/36)/(1/26) ใช้ตัวหารเฉพาะตัวที่ไม่ป่วยจึงเป็น odds ratio และ (23/59) - (1/27) เป็นผลต่างของความเสี่ยง คือ attributable risk",
    "source": "Study Design หน้า 27-28; Measurement of disease frequency- measurement of association- diagnostic test หน้า 49, 60; Data analysis & applied statistic for epidemiology_TC หน้า 142; 8 - Observational_study_2567 deck 2024 หน้า 32, 34",
