    "passage": "โคที่เป็นเต้านมอักเสบหลังคลอด แยกตามที่คลอด (จำนวนเป็นตัว ความเสี่ยงเป็นค่าประมาณ)\n\n| | เป็นเต้านมอักเสบ | โคทั้งหมด | ความเสี่ยง |\n|---|---|---|---|\n| คลอดนอกซองคลอด | 23 | 59 | 0.39 |\n| คลอดในซองคลอด | 1 | 27 | 0.04 |",
