    "explain": "Attributable risk หรือ risk difference คือความเสี่ยงของกลุ่มที่สัมผัสลบด้วยความเสี่ยงของกลุ่มที่ไม่สัมผัส 0.39 - 0.04 = 0.35 เป็นความเสี่ยงส่วนเกินที่มาจากปัจจัย คือภาระโรคที่อาจป้องกันได้ ถ้าโคกลุ่มนี้คลอดในซองคลอด ความเสี่ยงเต้านมอักเสบจะลดลงได้ 0.35 หรือ 35% ค่า 0.90 คือ attributable fraction ซึ่งเป็น AR หารด้วยความเสี่ยงของกลุ่มที่สัมผัส ค่า 0.39 คือความเสี่ยงของกลุ่มที่สัมผัสเอง และการแปลเป็นจำนวนเท่าเป็นความหมายของ relative risk ไม่ใช่ AR",
