    "options": [
      "0.35 คือสัดส่วนของเต้านมอักเสบในโคที่คลอดนอกซองที่เกิดจากการคลอดนอกซอง",
      "0.90 คือสัดส่วนของเต้านมอักเสบในโคทั้งฝูงที่เกิดจากการคลอดนอกซองคลอด",
      "0.90 คือสัดส่วนของเต้านมอักเสบในโคที่คลอดนอกซองที่เกิดจากการคลอดนอกซอง",
      "0.39 คือสัดส่วนของเต้านมอักเสบในโคที่คลอดนอกซองที่เกิดจากการคลอดนอกซอง"
    ],
    "answer": 2,
    "explain": "Attributable fraction บอกว่าโรคในกลุ่มที่สัมผัสปัจจัยเป็นสัดส่วนเท่าใดที่เกิดจากปัจจัยนั้น\n**สูตร** AF = AR หารด้วยความเสี่ยงของกลุ่มที่สัมผัส\n**แทนค่า** (0.39 - 0.04)/0.39 = 0.35/0.39 = 0.90\n**แปลผล** เต้านมอักเสบในโคที่คลอดนอกซองคลอดราว 90% มาจากการคลอดนอกซอง และป้องกันได้ถ้าไม่มีปัจจัยนี้\n\n**ข้อควรระวัง**\n— ค่านี้ใช้กับกลุ่มที่สัมผัสเท่านั้น ถ้าต้องการสัดส่วนในประชากรทั้งฝูงต้องใช้ population attributable risk proportion ซึ่งเทียบกับความเสี่ยงของประชากรรวม\n— 0.35 คือ AR ซึ่งเป็นผลต่างของความเสี่ยง ไม่ใช่สัดส่วนของโรค",
    "explainSay": "Attributable fraction บอกว่าโรคในกลุ่มที่สัมผัสปัจจัยเป็นสัดส่วนเท่าใดที่เกิดจากปัจจัยนั้น AF = AR หารด้วยความเสี่ยงของกลุ่มที่สัมผัส = (0.39 - 0.04)/0.39 = 0.35/0.39 = 0.90 แปลว่าเต้านมอักเสบในโคที่คลอดนอกซองคลอดราว 90% มาจากการคลอดนอกซอง และป้องกันได้ถ้าไม่มีปัจจัยนี้ ค่านี้ใช้กับกลุ่มที่สัมผัสเท่านั้น ถ้าต้องการสัดส่วนในประชากรทั้งฝูงต้องใช้ population attributable risk proportion ซึ่งเทียบกับความเสี่ยงของประชากรรวม ส่วน 0.35 คือ AR ซึ่งเป็นผลต่างของความเสี่ยง ไม่ใช่สัดส่วนของโรค",
