    "answer": 0,
    "explain": "Recall bias เกิดเมื่อผู้ให้ข้อมูลสองกลุ่มจำเหตุการณ์ในอดีตได้ไม่เท่ากัน ในที่นี้ฟาร์ม case จำการซื้อโคสาวได้ชัดกว่าฟาร์ม control ข้อมูลการสัมผัสของสองกลุ่มจึงคลาดเคลื่อนไม่เท่ากัน อคติแต่ละชนิดแยกได้จากคำถามที่ถาม selection bias ถามว่าใครถูกเลือกเข้าการศึกษา information bias ถามว่าวัด exposure หรือ outcome อย่างไร detection bias ถามว่าผู้ประเมินรู้หรือไม่ว่าสัตว์อยู่กลุ่มใด และ recall bias ถามว่าจำอดีตได้ต่างกันหรือไม่ ส่วน survivor bias เป็นปัญหาของ cross-sectional ที่สัตว์หรือฟาร์มที่ป่วยหนักหายไปก่อนวันสำรวจ",
