    "explain": "data analysis เป็นขั้นที่ต่อจากการเก็บข้อมูลในกระบวนการเฝ้าระวัง ก่อนวิเคราะห์ต้องตกลงว่าใครวิเคราะห์ ใช้วิธีใด และบ่อยเพียงใด แล้วจึงบรรยายข้อมูลตาม time, place และ person การกระจายตามเวลาใช้ติดตามโปรแกรมควบคุมโรคและตรวจพบการเปลี่ยนแปลงของโรคประจำถิ่นได้เร็ว การกระจายตามสถานที่บอกพื้นที่ที่เกิดโรค และการกระจายตามลักษณะประชากรบอกกลุ่มสัตว์ที่ป่วย จากนั้นข้อมูลจึงนำไปวิเคราะห์ทางสถิติทั้งเชิงพรรณนาและเชิงวิเคราะห์",
