    "q": "การเฝ้าระวังเพื่อค้นหาผู้ป่วย (case finding) ซึ่งเป็นวัตถุประสงค์หนึ่งเมื่อมีโรคอยู่ในพื้นที่ (present of disease) มีประสิทธิผลขึ้นกับปัจจัยใดเป็นหลัก",
