    "q": "ภูมิคุ้มกันของสัตว์ในพื้นที่ลดลงจากภาวะทุพโภชนาการหรือการกดภูมิคุ้มกันจนเกิดการระบาด จัดเป็นสาเหตุของการระบาด (causes of outbreak) แบบใด",
