    "answer": 1,
    "explain": "สาเหตุของการระบาดมีห้าแบบ ได้แก่ เชื้อมีปริมาณหรือความรุนแรงเพิ่มขึ้น เชื้อเข้าสู่สิ่งแวดล้อมหรือพื้นที่ใหม่ การแพร่ของโรคมีประสิทธิภาพขึ้นจนสัตว์ไวรับสัมผัสเชื้อมากขึ้น ความไวรับของ host เปลี่ยนไป และ host สัมผัสเชื้อมากขึ้นหรือมีทางเข้าใหม่ ภูมิคุ้มกันที่ลดลงจากทุพโภชนาการหรือการกดภูมิคุ้มกัน รวมทั้งการเปลี่ยนแปลงทางพันธุกรรมหรือสรีรวิทยาของประชากร จัดเป็นการเปลี่ยนแปลงความไวรับของ host ส่วน increased host exposure หมายถึงการเปลี่ยนพฤติกรรมหรือแนวทางการเลี้ยง เช่น ตลาดค้าสัตว์มีชีวิต สิ่งแวดล้อมถูกรบกวน เช่น การตัดไม้ทำลายป่าหรือน้ำท่วม หรือหัตถการที่นำเชื้อเข้าสู่ร่างกาย",
