    "q": "จากการระบาดของ vibriosis ผู้ที่กินหอยนางรม 100 คน ป่วย 20 คน และผู้ที่ไม่ได้กิน 100 คน ป่วย 1 คน ได้ relative risk เท่ากับ 20 ข้อใดแปลผลได้ถูกต้อง",
