    "explain": "WHO นิยาม public health surveillance ว่าเป็นการเก็บ วิเคราะห์ และแปลผลข้อมูลที่เกี่ยวกับสุขภาพอย่างต่อเนื่องและเป็นระบบ ซึ่งจำเป็นต่อการวางแผน การดำเนินการ และการประเมินผลงานสาธารณสุข ข้อมูลจากระบบเฝ้าระวังจึงเป็นหลักฐาน (evidence base) สำหรับการวางแผนและการประเมินมาตรการ ส่วนกิจกรรมประจำเพื่อตรวจจับการเปลี่ยนแปลงของค่าทางระบาดวิทยาคือนิยามของ monitoring การค้นหาผู้ป่วยเพิ่มและแหล่งโรคระหว่างการระบาดคือ outbreak surveillance และการรายงานผู้ป่วยรายตัวตามรายชื่อโรคคือลักษณะของ passive surveillance ซึ่งเป็นการเฝ้าระวังเพียงชนิดหนึ่ง",
