    "type": "mcq",
    "q": "การนำไก่ที่ปลอดเชื้อไปเลี้ยงไว้ในพื้นที่เสี่ยง แล้วเจาะเลือดตรวจหาแอนติบอดีเป็นระยะ เพื่อให้รู้เร็วว่ามีเชื้อเข้ามาในพื้นที่ เป็นการเฝ้าระวังแบบใด",
    "options": [
      "Syndromic surveillance",
      "Risk factor surveillance",
      "Sentinel surveillance",
      "Outbreak surveillance"
    ],
    "answer": 2,
    "explain": "sentinel surveillance มุ่งเฝ้าระวังในประชากรย่อยที่เลือกไว้ เพื่อเพิ่มโอกาสตรวจพบโรคหรือให้คุ้มค่ากว่า เป้าหมายคือได้ข้อมูลทันเวลาด้วยค่าใช้จ่ายไม่สูง มากกว่าการประมาณความชุกหรืออุบัติการณ์ที่แม่นยำของประชากรทั้งหมด sentinel อาจเป็นสัตว์ตัวเดียวจนถึงฝูง เป็นสัตว์ชนิดเดียวกันหรือชนิดที่ไวรับกว่า และอาจนำเข้าไปวางไว้หรือเป็นสัตว์ที่อยู่ในพื้นที่อยู่แล้ว เช่น ไก่ที่นำไปเลี้ยงในพื้นที่เสี่ยงแล้วตรวจแอนติบอดี ในงานสาธารณสุข sentinel อาจเป็นสถานพยาบาลที่คัดเลือกให้รายงานโรค เช่น รายงานผู้ป่วยอาการคล้ายไข้หวัดใหญ่ทุกสัปดาห์เพื่อดูแนวโน้มของโรค ส่วน syndromic surveillance ดูกลุ่มอาการก่อนยืนยันการวินิจฉัย risk factor surveillance ดูปัจจัยเสี่ยงด้านสิ่งแวดล้อม พฤติกรรม หรือชีวภาพ เช่น ดักยุงตรวจหา West Nile virus และ outbreak surveillance ค้นหาผู้ป่วยเพิ่มและแหล่งโรคระหว่างการระบาด",
