    "model_answer": "แบ่งเป็นสองด้าน ด้านคุณภาพข้อมูล (data quality) คือ เร่งการรายงานข้อมูลผู้ป่วยจากการเฝ้าระวังระดับประเทศ ปรับปรุงคุณภาพของข้อมูล และรวบรวมข้อมูลให้ครบถ้วน ด้านการปรับปรุงระบบ (improve system) คือ พัฒนาการเฝ้าระวังให้ทันสมัยอย่างต่อเนื่องด้วยการรายงานผู้ป่วยแบบอิเล็กทรอนิกส์ (electronic case reporting) ที่แลกเปลี่ยนข้อมูลรายงานผู้ป่วยอัตโนมัติแบบ real-time ซึ่งช่วยให้ทบทวนข้อมูลและดำเนินการได้ทันเวลา (timely review and action)",
    "explain": "การปรับปรุงการเฝ้าระวังมุ่งให้ข้อมูลมาเร็ว ถูกต้อง และครบ และให้ระบบส่งต่อข้อมูลได้ทันที เพราะข้อมูลเฝ้าระวังมีค่าเมื่อนำไปสู่การตัดสินใจและการลงมือได้ทันเวลา ส่วนการควบคุมคุณภาพข้อมูลในระบบทำได้ด้วยการฝึกอบรมเจ้าหน้าที่ การวางแผนเก็บข้อมูลที่ดี นักระบาดวิทยาที่ตื่นตัว และการตรวจสอบยืนยันข้อมูล",
