    "type": "mcq",
    "q": "การจัดตั้งเขตปลอดโรคปากและเท้าเปื่อยในภาคตะวันออกของประเทศไทยใช้การแบ่งเขตตามกฎหมาย (legislative zoning) เขตที่ประกาศเพื่อป้องกันการแพร่ระบาดของโรคเข้าสู่เขตปลอดโรคระบาดหรือเข้าในราชอาณาจักร คือเขตใด",
    "options": [
      "เขตกันชนโรคระบาด",
      "เขตควบคุมโรคระบาด",
      "เขตปลอดโรคระบาด",
      "เขตโรคระบาด"
    ],
    "answer": 0,
    "explain": "รัฐมนตรีมีอำนาจประกาศเขตเพื่อป้องกันและควบคุมโรคระบาด ได้แก่ เขตควบคุมโรคระบาด (control zone) เพื่อป้องกันและควบคุมการแพร่ระบาดของโรคชนิดหนึ่งหรือหลายชนิด เขตปลอดโรคระบาด (free zone) เมื่อควบคุมจนไม่มีโรคระบาดในพื้นที่นั้นได้ และเขตกันชนโรคระบาด (buffer zone) เพื่อป้องกันการแพร่ระบาดเข้าสู่เขตปลอดโรคระบาดหรือเข้าในราชอาณาจักร และห้ามเคลื่อนย้ายสัตว์หรือซากสัตว์เข้าออกหรือผ่านทั้งสามเขตเว้นแต่ได้รับอนุญาต การสร้างเขตปลอดโรคปากและเท้าเปื่อยในภาคตะวันออกใช้ทั้ง control zone และ buffer zone ร่วมกับระบบเครื่องหมายและขึ้นทะเบียนสัตว์แห่งชาติ (NID) การทำวัคซีนแบบครอบคลุม การเฝ้าระวังเชิงรุกและเชิงรับ และการควบคุมการเคลื่อนย้ายสัตว์ ส่วนเขตโรคระบาดเป็นพื้นที่ที่ประกาศเมื่อพบโรคแล้ว เพื่อสั่งปิดตลาด ห้ามเคลื่อนย้ายสัตว์ และกำหนดมาตรการควบคุม",
    "source": "7. Disease Control, Prevention and Eradication (การควบคุม ป้องกัน และกำจัดโรค) หน้า 43; นโยบายภาครัฐ และการป้องกัน ควบคุมและกำจัดโรคระบาดสัตว์ หน้า 55; 3. Report outbreak SJ 2026 หน้า 10; 10 - Control_Prevention_Eradication_Epi2024 deck 2024 หน้า 24",
