    "q": "การวัดความถี่ของการเกิดโรค (disease frequency) ในรูปอุบัติการณ์ (incidence) ซึ่งนับเฉพาะผู้ป่วยรายใหม่ที่เกิดขึ้นในช่วงเวลาหนึ่ง แบ่งออกเป็นสองแบบตามข้อใด",
