    "answer": 2,
    "explain": "อุบัติการณ์วัดผู้ป่วยรายใหม่ที่เกิดขึ้นในช่วงเวลาหนึ่ง แบ่งเป็น cumulative incidence ซึ่งเป็นสัดส่วนของสัตว์ในประชากรเสี่ยงที่ป่วยใหม่ มีค่าระหว่าง 0 ถึง 1 และไม่มีหน่วย กับ incidence rate ซึ่งหารจำนวนป่วยใหม่ด้วยผลรวมเวลาที่สัตว์แต่ละตัวอยู่ในภาวะเสี่ยง เช่น ต่อ animal-year จึงบอกความเร็วของการเกิดโรค ส่วน point prevalence กับ period prevalence เป็นความชุก ซึ่งนับผู้ป่วยที่มีอยู่ทั้งหมดไม่ใช่เฉพาะรายใหม่ และ relative risk กับ odds ratio หรือ prevalence ratio กับ incidence rate ratio เป็นค่าที่เปรียบเทียบความถี่ระหว่างสองกลุ่ม (measure of association) ไม่ใช่ค่าความถี่ของโรคเอง",
