    "q": "จากตาราง คำนวณ RR (S&V เทียบกับ Lambeth) ได้ 5.35 ข้อใดแปลผลได้ถูกต้อง",
    "say": "การระบาดของอหิวาต์ในลอนดอนปี 1854 เขตที่รับน้ำจากบริษัท Southwark & Vauxhall (S&V) เพียงบริษัทเดียวมีประชากร 167,654 คน ตายจากอหิวาต์ 844 คน ส่วนเขตที่รับน้ำจากบริษัท Lambeth เพียงบริษัทเดียวมีประชากร 19,133 คน ตาย 18 คน คำนวณ RR (S&V เทียบกับ Lambeth) ได้ 5.35 ข้อใดแปลผลได้ถูกต้อง",
    "passage": "การระบาดของอหิวาต์ในลอนดอนปี 1854 เปรียบเทียบเขตที่รับน้ำจากบริษัทเดียว ตารางแสดงประชากรและจำนวนที่ตายจากอหิวาต์ (คน)\n\n| เขตที่รับน้ำจาก | ประชากร | ตาย |\n|---|---|---|\n| Southwark & Vauxhall (S&V) | 167,654 | 844 |\n| Lambeth | 19,133 | 18 |",
    "passage_title": "การระบาดของอหิวาต์ในลอนดอนปี 1854",
