    "type": "mcq",
    "q": "ในการระบาดของอหิวาต์ปี 1854 เขตที่รับน้ำจากบริษัทใดบริษัทหนึ่งเพียงบริษัทเดียวอาจมีลักษณะอื่นที่ทำให้มีคนตายมากหรือน้อยต่างกันได้ จึงเลือกวิเคราะห์เฉพาะเขตที่รับน้ำจากทั้งสองบริษัท (S&V และ Lambeth) แล้วเปรียบเทียบบ้านที่ได้น้ำจากแต่ละบริษัท การทำเช่นนี้มีจุดประสงค์หลักเพื่ออะไร",
    "options": [
      "เพื่อเพิ่มขนาดตัวอย่างในการวิเคราะห์ ให้การทดสอบทางสถิติมี power สูงขึ้นกว่าเดิม",
      "เพื่อเปลี่ยนรูปแบบการศึกษาจาก observational เป็น experimental study",
      "เพื่อลดความคลาดเคลื่อนในการวินิจฉัยว่าผู้ตายเป็นอหิวาต์จริงหรือไม่",
      "เพื่อตัดตัวแปรกวน (confounder) ให้สองกลุ่มที่เทียบกันมีลักษณะอื่นคล้ายกัน"
    ],
    "answer": 3,
    "explain": "ตัวแปรกวน (confounder) คือปัจจัยที่สัมพันธ์ทั้งกับปัจจัยที่สนใจและกับผลลัพธ์ และไม่อยู่บนเส้นทางเหตุและผลระหว่างทั้งสอง จึงทำให้ความสัมพันธ์ที่เห็นเพี้ยนไปจากความจริง เขตที่ใช้น้ำจากบริษัทต่างกันอาจต่างกันในเรื่องอื่นที่มีผลต่อการตายด้วย การจำกัดการวิเคราะห์ไว้เฉพาะเขตที่รับน้ำจากทั้งสองบริษัททำให้บ้านที่นำมาเทียบกันอยู่ในพื้นที่เดียวกันและมีลักษณะอื่นคล้ายกัน ซึ่งเป็นการควบคุม confounding ในขั้นออกแบบด้วยการจำกัดกลุ่มที่ศึกษา (restriction) จุดประสงค์จึงไม่ใช่การเพิ่ม power หรือการยืนยันการวินิจฉัย และการศึกษายังเป็นการสังเกตสิ่งที่เกิดขึ้นเอง ไม่ใช่การที่ผู้วิจัยกำหนดให้กลุ่มใดได้รับน้ำแบบ experimental study",
    "source": "Study Design หน้า 5, 35, 39; Concept of causation_TC 3 August 2026 หน้า 10-11; 11 - Applied_Statistics_in_Epidemiology_2024 deck 2024 หน้า 10",
