    "q": "จากตาราง ได้ RR (S&V เทียบกับ Lambeth) = 8.19 (95% CI 6.43–10.36) ข้อสรุปใดเกินกว่าที่ผลนี้บอกได้",
    "say": "เมื่อวิเคราะห์เฉพาะบ้านในเขตที่รับน้ำจากทั้งสองบริษัท พบว่าบ้านที่ได้น้ำจาก S&V มีประชากร 98,862 คน ตายจากอหิวาต์ 419 คน (4.2 ต่อ 1,000) ส่วนบ้านที่ได้น้ำจาก Lambeth มีประชากร 154,615 คน ตาย 80 คน (0.5 ต่อ 1,000) ได้ RR (S&V เทียบกับ Lambeth) = 8.19 (95% CI 6.43–10.36) ข้อสรุปใดเกินกว่าที่ผลนี้บอกได้",
    "passage": "วิเคราะห์เฉพาะบ้านในเขตที่รับน้ำจากทั้งสองบริษัท ตารางแสดงประชากรและจำนวนที่ตายจากอหิวาต์ (คน)\n\n| บ้านที่ได้น้ำจาก | ประชากร | ตาย | ตายต่อ 1,000 คน |\n|---|---|---|---|\n| S&V | 98,862 | 419 | 4.2 |\n| Lambeth | 154,615 | 80 | 0.5 |",
