    "q": "ในการศึกษาทางระบาดวิทยา แนวคิดที่ว่าการเกิดโรคไม่ได้เกิดแบบสุ่ม (disease occurrence is not random) นำไปสู่การใช้สถิติอย่างไร",
    "options": [
      "ใช้พิสูจน์ว่าปัจจัยที่พบร่วมกับโรคเป็นสาเหตุของโรค โดยไม่ต้องพิจารณาสิ่งอื่น",
      "ใช้ทดสอบว่าความต่างของการเกิดโรคระหว่างกลุ่มไม่ได้เกิดจากความบังเอิญ",
      "ใช้ยืนยันว่าโรคกระจายเท่า ๆ กันในทุกช่วงเวลา ทุกพื้นที่ และทุกกลุ่มสัตว์",
      "ใช้แทนการเก็บข้อมูลเวลา สถานที่ และตัวสัตว์ที่ป่วย เมื่อมีข้อมูลตัวเลขมากพอ"
    ],
    "answer": 1,
    "explain": "การเกิดโรคไม่ได้กระจายแบบสุ่ม แต่มักเกิดกับบางกลุ่มมากกว่ากลุ่มอื่นตามเวลา สถานที่ และตัวสัตว์ (time, place, person) จึงบ่งว่ามีปัจจัยที่ต้องค้นหา สถิติเป็นเครื่องมือทดสอบสมมติฐาน (significance test) ว่าความต่างที่เห็นระหว่างกลุ่มน่าจะเป็นความต่างจริงหรือเกิดจากความบังเอิญ โดยใช้ p-value ประกอบการตัดสิน แต่ผลที่มีนัยสำคัญยังเป็นเพียงความสัมพันธ์ ไม่ได้พิสูจน์ว่าปัจจัยนั้นเป็นสาเหตุ สถิติไม่ได้ใช้ยืนยันว่าโรคกระจายเท่ากันทุกกลุ่ม ซึ่งตรงข้ามกับแนวคิดนี้ และไม่ได้ใช้แทนข้อมูลเวลา สถานที่ และตัวสัตว์ เพราะการทดสอบต้องอาศัยข้อมูลเหล่านี้",
