    "id": 214628,
    "subject": "epidemiology",
    "topic": "epidem-applied-stats",
    "year": 5,
    "type": "mcq",
    "q": "สัตวแพทย์สังเกตว่าในคลินิกมักพบแมวเพศผู้ป่วยเป็น feline idiopathic cystitis (FIC) มากกว่าแมวเพศเมีย และพบในแมวเปอร์เซียมากกว่าพันธุ์อื่น ข้อใดเป็นการใช้ข้อสังเกตนี้อย่างเหมาะสมที่สุด",
    "options": [
      "สรุปได้ทันทีว่าเพศผู้เป็นปัจจัยเสี่ยงของ FIC เพราะพบในคลินิกบ่อยกว่าเพศเมีย",
      "สรุปได้ว่าพันธุ์เปอร์เซียเป็นสาเหตุของ FIC เพราะพบมากกว่าพันธุ์อื่นในคลินิก",
      "ใช้จำนวนแมวป่วยในคลินิกคำนวณอุบัติการณ์ของ FIC ในประชากรแมวทั้งประเทศได้",
      "ถือว่าอาจเป็นอคติ (bias) แล้วทดสอบด้วยการศึกษาที่มีกลุ่มเปรียบเทียบ"
    ],
    "answer": 3,
    "explain": "สิ่งที่พบในคลินิกอาจเป็นอคติ (bias) ได้ เช่น selection bias ที่เกิดจากว่าสัตว์ตัวใดมาถึงคลินิกหรือเข้ามาอยู่ในข้อมูล ความสัมพันธ์ที่เห็นจึงอาจไม่ใช่ของจริง (spurious association) ก่อนสรุปว่าเพศหรือพันธุ์สัมพันธ์กับ FIC ต้องค้นหาความจริงด้วยการศึกษาทางระบาดวิทยาที่มีกลุ่มเปรียบเทียบ เช่น case-control study ที่เทียบสัดส่วนแมวเพศผู้หรือแมวเปอร์เซียระหว่างแมวที่เป็นและไม่เป็น FIC หรือ cohort study ที่ติดตามแมวสองกลุ่มไปข้างหน้า การพบบ่อยในคลินิกจึงยังสรุปเป็นปัจจัยเสี่ยงหรือสาเหตุไม่ได้ และจำนวนแมวป่วยที่มาคลินิกไม่มีประชากรเสี่ยงที่ชัดเจนเป็นตัวหาร จึงใช้คำนวณอุบัติการณ์ของประชากรไม่ได้",
    "source": "Concept of causation_TC 3 August 2026 หน้า 9; Study Design หน้า 14, 20, 34; Measurement of disease frequency- measurement of association- diagnostic test หน้า 11; 11 - Applied_Statistics_in_Epidemiology_2024 deck 2024 หน้า 13-14",
