    "q": "การเปรียบเทียบน้ำหนักแรกคลอดของทารกระหว่างแม่ที่ไม่สูบบุหรี่กับแม่ที่สูบบุหรี่ ได้ mean difference = 281.71 และ 95% CI ของ mean difference = (70.69, 492.73) ข้อใดแปลความหมายของช่วงนี้ได้ถูกต้อง",
    "options": [
      "เรามั่นใจ 95% ว่าช่วง 70.69 ถึง 492.73 ครอบค่าความต่างที่แท้จริงของประชากร",
      "ทารก 95% ในการศึกษานี้มีน้ำหนักแรกคลอดต่างกันอยู่ระหว่าง 70.69 ถึง 492.73",
      "ค่าความต่างที่แท้จริงของประชากรเท่ากับ 281.71 แน่นอน ส่วนช่วงนี้เป็นค่าคลาดเคลื่อน",
      "มีโอกาส 95% ที่ผลการศึกษาครั้งนี้เกิดจากความบังเอิญ เพราะช่วงกว้างมาก"
    ],
    "answer": 0,
    "explain": "เราไม่มีทางรู้ค่าความต่างที่แท้จริงของประชากร จึงต้องประมาณจากตัวอย่าง ค่า 281.71 เป็นค่าประมาณแบบจุด (point estimate) ส่วน 95% CI เป็นค่าประมาณแบบช่วง (interval estimate) ถ้าทำการประมาณซ้ำหลายครั้ง ช่วงที่สร้างด้วยวิธีนี้ราว 95% จะครอบค่าจริงของประชากร จึงแปลแบบง่ายว่าเรามั่นใจ 95% ว่าช่วง 70.69 ถึง 492.73 ครอบค่าความต่างที่แท้จริง ช่วงนี้เป็นช่วงของค่าเฉลี่ยความต่างของประชากร ไม่ใช่ช่วงที่น้ำหนักของทารกแต่ละคนต่างกัน และไม่ได้บอกว่าค่าจริงเท่ากับ 281.71 แน่นอน ส่วนตัวเลข 95% ไม่ได้แปลว่ามีโอกาส 95% ที่ผลเกิดจากความบังเอิญ การตัดสินเรื่องความบังเอิญดูจาก p-value หรือดูว่าช่วงความเชื่อมั่นครอบค่า null value (ผลต่างเท่ากับ 0) หรือไม่",
