      "ค่าทำนายอยู่ระหว่าง 0 ถึง 1 เสมอ จึงใช้ทำนายค่าที่มากกว่า 1 ไม่ได้",
      "ค่าทำนายเป็นได้ตั้งแต่ −∞ ถึง ∞ จึงไม่ควรทำนายเมื่อค่า X อยู่นอกช่วงของข้อมูล"
