    "answer": 3,
    "explain": "Linear regression ให้เส้นตรงซึ่งค่าทำนายเพิ่มหรือลดได้ไม่มีขอบเขต ตั้งแต่ −∞ ถึง ∞ และตัวแปรตาม (Y) ต้องเป็นตัวแปรเชิงปริมาณต่อเนื่อง การนำสมการไปทำนายเมื่อค่า X อยู่นอกช่วงของข้อมูลที่ใช้สร้างสมการจึงเสี่ยงต่อค่าที่ผิดจากความจริง ส่วนตัวแปรต้นวิเคราะห์ได้ทุกชนิดทั้งเชิงปริมาณและเชิงกลุ่ม และใส่ได้หลายตัวพร้อมกันเป็น multiple regression ซึ่งช่วยควบคุม confounding effect ค่าทำนายที่ถูกจำกัดอยู่ระหว่าง 0 ถึง 1 (0–100%) เป็นลักษณะของความน่าจะเป็นจาก logistic regression ไม่ใช่ linear regression",
