    "type": "mcq",
    "q": "เมื่อต้องการทราบว่าปัจจัยหลายตัวมีผลต่อการเกิดโรค (เกิด/ไม่เกิด) หรือไม่ เหตุใดจึงใช้ logistic regression แทน linear regression",
    "options": [
      "เพราะ logistic regression ใช้ได้กับตัวแปรต้นเพียงตัวเดียว จึงไม่ต้องกังวลเรื่อง confounding และได้ค่า RR ที่แปลผลได้โดยตรง",
      "เพราะ linear regression ให้ค่าทำนายอยู่ระหว่าง 0 ถึง 1 เสมอ จึงแยกสัตว์ป่วยกับไม่ป่วยไม่ได้ ส่วน logistic regression ไม่มีข้อจำกัดนี้",
      "เพราะ linear regression ต้องการ Y เชิงปริมาณ และค่าทำนายสัดส่วนอาจเกิน 100% หรือติดลบ ส่วน logistic regression ให้ค่าอยู่ระหว่าง 0–100%",
      "เพราะ logistic regression ไม่ต้องแปลงค่าใด ๆ ค่า coefficient ที่ได้จึงเป็น odds ratio ที่นำไปแปลผลได้ทันที ต่างจาก linear regression"
    ],
    "answer": 2,
    "explain": "ในทางระบาดวิทยา ตัวแปรตามมักเป็นการเกิดโรค ซึ่งเป็นตัวแปรเชิงคุณภาพแบบสองค่า (เกิด/ไม่เกิด) และสิ่งที่ต้องการไม่ใช่แค่ต่างหรือไม่ต่าง แต่เป็นขนาดความสัมพันธ์ เช่น OR หรือ RR linear regression ต้องการตัวแปรตามเชิงปริมาณ ถ้าแปลงผลเป็นสัดส่วนแล้วใช้เส้นตรงทำนาย ค่าที่ได้เป็นไปได้ตั้งแต่ −∞ ถึง ∞ จึงอาจเกิน 100% หรือติดลบ ซึ่งเป็นไปไม่ได้สำหรับโอกาสเกิดโรค logistic regression ใช้ logit หรือ log(odds) เป็นตัวแปรตาม ทำให้ความน่าจะเป็นที่ทำนายอยู่ระหว่าง 0–100% วิเคราะห์ X ได้หลายตัวพร้อมกัน และแปลง coefficient ด้วย exponential เป็น odds ratio ได้ ข้อความที่ว่า logistic regression ใช้ X ได้ตัวเดียว ให้ค่า RR หรือได้ coefficient เป็น OR โดยไม่ต้องแปลงจึงผิด และค่าที่ถูกจำกัดระหว่าง 0 ถึง 1 เป็นลักษณะของ logistic ไม่ใช่ linear regression",
