    "type": "mcq",
    "q": "การศึกษาสมมุติแบบ case-control ว่าเพศชายเป็นปัจจัยเสี่ยงของการติดเชื้อมาลาเรียหรือไม่ ได้ข้อมูลดังนี้ เพศชาย: case 88 คน, control 68 คน; เพศหญิง: case 62 คน, control 82 คน ค่า odds ratio และการแปลผลข้อใดถูกต้อง",
    "options": [
      "OR = 1.71; odds ของการติดเชื้อมาลาเรียในเพศหญิงเป็น 1.71 เท่าของเพศชาย",
      "OR = 1.06; เพศชายและเพศหญิงมี odds ของการติดเชื้อมาลาเรียใกล้เคียงกัน",
      "OR = 1.00; เพศชายเป็น protective factor ของการติดเชื้อมาลาเรียในการศึกษานี้",
      "OR = 1.71; odds ของการติดเชื้อมาลาเรียในเพศชายเป็น 1.71 เท่าของเพศหญิง"
    ],
    "answer": 3,
    "explain": "**สูตร** OR = ad/bc\n**แทนค่า** (88 × 82)/(68 × 62) ≈ 1.71\n**แปลผล** ในการศึกษาแบบ case-control คือ odds ของการเป็นเพศชายในกลุ่ม case เทียบกับในกลุ่ม control ซึ่งแปลผลได้ว่า odds ของการติดเชื้อมาลาเรียในเพศชายเป็น 1.71 เท่าของเพศหญิง (OR มากกว่า 1 คือสัมพันธ์เชิงบวก)\n\n❌ ทำไมข้ออื่นผิด\n— \"odds ของการติดเชื้อมาลาเรียในเพศหญิงเป็น 1.71 เท่าของเพศชาย\" กลับทิศให้เพศหญิงเป็นฝ่ายที่สูงกว่าจึงผิด\n— \"OR = 1.06\" และ \"OR = 1.00\" ไม่ใช่ผลของการคำนวณข้อมูลชุดนี้\n— OR เท่ากับ 1 หมายถึงไม่มีความสัมพันธ์ ไม่ใช่ protective factor ซึ่งต้องมี OR น้อยกว่า 1",
    "explainSay": "OR = ad/bc = (88 × 82)/(68 × 62) ≈ 1.71 ในการศึกษาแบบ case-control คือ odds ของการเป็นเพศชายในกลุ่ม case เทียบกับในกลุ่ม control ซึ่งแปลผลได้ว่า odds ของการติดเชื้อมาลาเรียในเพศชายเป็น 1.71 เท่าของเพศหญิง (OR มากกว่า 1 คือสัมพันธ์เชิงบวก) การกลับทิศให้เพศหญิงเป็นฝ่ายที่สูงกว่าจึงผิด ส่วน 1.06 และ 1.00 ไม่ใช่ผลของการคำนวณข้อมูลชุดนี้ และ OR เท่ากับ 1 หมายถึงไม่มีความสัมพันธ์ ไม่ใช่ protective factor ซึ่งต้องมี OR น้อยกว่า 1",
    "source": "Measurement of disease frequency- measurement of association- diagnostic test หน้า 60, 62, 65, 70; 11 - Applied_Statistics_in_Epidemiology_2024 deck 2024 หน้า 43",
    "verified": "สไลด์ Applied Statistics in Epidemiology ชุดปี 2567 หน้า 43 มาร์คในสำเนาจากชุดไฟล์ของ Vet 84 (หน้าไม่ได้ระบุรุ่นผู้มาร์ค)",
