    "q": "การศึกษาว่าการสูบบุหรี่ เชื้อชาติ และอายุของแม่ มีผลต่อการเกิดน้ำหนักแรกคลอดน้อย (ใช่/ไม่ใช่) หรือไม่ โดยพิจารณาปัจจัยทั้งสามพร้อมกัน สะท้อนแนวคิดใดเกี่ยวกับสาเหตุของการเกิดโรค",
    "options": [
      "One-to-one causal relationship ที่ปัจจัยหนึ่งก่อผลหนึ่งตาม Koch's postulates",
      "Multifactorial causation ที่ผลลัพธ์หนึ่งเกิดได้จากหลายปัจจัยร่วมกัน",
      "Spurious association ที่ความสัมพันธ์เกิดจากความบังเอิญหรืออคติ",
      "Dose-response relationship ที่ความเสี่ยงเพิ่มตามขนาดของการสัมผัส"
    ],
    "answer": 1,
    "explain": "การเกิดโรคหรือผลลัพธ์หนึ่งมักไม่ได้มาจากปัจจัยเดียว แต่เกิดจากหลายปัจจัยร่วมกันในเครือข่ายของสาเหตุ (web of causation) ซึ่งเรียกว่า multifactorial causation การวิเคราะห์การสูบบุหรี่ เชื้อชาติ และอายุของแม่พร้อมกันจึงจำเป็น และปัจจัยเหล่านี้อาจเป็นตัวแปรกวนของกันและกันได้ ขึ้นกับว่าเราสนใจปัจจัยใดเป็นหลัก แนวคิดแบบ one-to-one ตาม Koch's postulates ใช้ได้ไม่ดีกับโรคจำนวนมากที่ต้องมีหลายปัจจัยร่วม spurious association เป็นความสัมพันธ์ที่ไม่จริงซึ่งเกิดจากความบังเอิญหรืออคติ และ dose-response เป็นเกณฑ์หนึ่งของ Bradford Hill ที่ดูว่าความเสี่ยงเพิ่มตามขนาดการสัมผัส ทั้งสามจึงไม่ใช่สิ่งที่การพิจารณาหลายปัจจัยพร้อมกันสะท้อน",
