    "type": "mcq",
    "q": "ในการถดถอยโลจิสติก ln(P/(1 − P)) = β0 + β1X1 + β2X2 + ... + βkXk ค่า regression coefficient (β) ที่ได้อยู่ในรูปใด และต้องทำอย่างไรจึงจะแปลผลเป็น odds ratio ได้",
    "options": [
      "อยู่ในรูป log(OR) ต้องแปลงด้วย exponential (e ยกกำลัง β) จึงได้ odds ratio",
      "อยู่ในรูป odds ratio อยู่แล้ว จึงแปลผลเป็นจำนวนเท่าได้ทันทีโดยไม่ต้องแปลงค่า",
      "อยู่ในรูปความน่าจะเป็น ต้องคูณด้วย 100 ก่อนเพื่อให้อยู่ในรูปเปอร์เซ็นต์",
      "อยู่ในรูป odds ต้องหารด้วย 1 บวก odds จึงจะได้ odds ratio ของปัจจัยนั้น"
    ],
    "answer": 0,
    "explain": "logistic regression ใช้ logit หรือ ln(odds) เป็นตัวแปรตาม ค่าที่ได้จากสมการจึงอยู่ในรูป log odds และ coefficient ของแต่ละตัวแปรคือผลต่างของ log odds เมื่อตัวแปรนั้นเพิ่มขึ้น 1 หน่วยหรือเปลี่ยนกลุ่ม ซึ่งก็คือ log(OR) ต้องแปลงด้วย exponential ก่อน คือ OR = e^β เช่น β เท่ากับ 0 ให้ OR เท่ากับ 1 คือไม่สัมพันธ์ coefficient จึงไม่ใช่ OR โดยตรงและไม่ใช่ความน่าจะเป็น ส่วนการหาร odds ด้วย 1 บวก odds เป็นการแปลง odds กลับเป็นความน่าจะเป็น ไม่ได้ให้ odds ratio",
