    "type": "mcq",
    "q": "ข้อใดจับคู่รูปแบบการศึกษากับค่าวัดความสัมพันธ์ที่ใช้ได้ถูกต้อง",
    "options": [
      "Case-control ใช้ได้ทั้ง RR และ OR; cohort ใช้ได้เฉพาะ OR เพราะเริ่มจากผลลัพธ์; cross-sectional ใช้ได้เฉพาะ RR",
      "Case-control ใช้ prevalence ratio; cohort ใช้ได้เฉพาะ OR; cross-sectional ใช้ได้เฉพาะ RR เพราะวัดทุกอย่างพร้อมกัน",
      "ทุกรูปแบบใช้ RR ได้เหมือนกัน เพราะคำนวณ risk ของกลุ่มสัมผัสและกลุ่มไม่สัมผัสได้เสมอในทุกรูปแบบการศึกษา",
      "Case-control ใช้ได้เฉพาะ OR; cohort ใช้ RR เป็นหลักและคำนวณ OR ได้; cross-sectional ใช้ prevalence ratio หรือ OR"
    ],
    "answer": 3,
    "explain": "case-control เลือกตัวอย่างจากผลลัพธ์ (เป็นโรคหรือไม่เป็นโรค) แล้วย้อนดูการสัมผัส จึงคำนวณ risk ที่แท้จริงของแต่ละกลุ่มไม่ได้ ใช้ได้เฉพาะ OR cohort ติดตามกลุ่มสัมผัสและไม่สัมผัสไปข้างหน้า คำนวณ incidence หรือ risk ได้จริง จึงใช้ RR เป็นหลักและคำนวณ OR ได้ด้วย ส่วน cross-sectional วัดการสัมผัสและโรคพร้อมกัน คำนวณ incidence หรือ risk ที่แท้จริงไม่ได้ จึงใช้ prevalence ratio หรือ OR เมื่อ OR ใช้ได้ในทุกรูปแบบ logistic regression ที่ให้ค่าเป็น OR จึงเป็นที่นิยม การเลือกค่าวัดและสถิติจึงขึ้นกับว่าใช้ study design แบบใด",
