    "q": "การวิเคราะห์การถดถอยนำไปใช้ได้สองแบบ ข้อใดจับคู่จุดประสงค์กับเกณฑ์ที่ใช้เลือกได้ถูกต้อง",
    "options": [
      "ดูปัจจัย X ที่สัมพันธ์กับ Y เลือกโมเดลที่ fit กับข้อมูลดีที่สุด; สร้างสมการทำนาย Y เลือกเฉพาะตัวแปรที่ p-value น้อยกว่า 0.05",
      "ดูปัจจัย X ที่สัมพันธ์กับ Y ใช้ X ได้ครั้งละตัวเดียวเท่านั้น; สร้างสมการทำนาย Y จึงใช้ X หลายตัวพร้อมกันได้",
      "ดูปัจจัย X ที่สัมพันธ์กับ Y เลือกตัวแปรที่ p-value มากกว่า 0.05; สร้างสมการทำนาย Y เลือกโมเดลที่มีตัวแปรน้อยที่สุด",
      "ดูปัจจัย X ที่สัมพันธ์กับ Y เลือกตัวแปรที่ p-value น้อยกว่า 0.05; สร้างสมการทำนาย Y เลือกโมเดลที่ fit กับข้อมูลดีที่สุด"
    ],
    "answer": 3,
    "explain": "การถดถอยใช้ได้ทั้งเพื่ออธิบายและเพื่อทำนาย ถ้าต้องการดูว่าปัจจัย X ใดสัมพันธ์กับ Y จะใส่ X ได้หลายตัว แล้วพิจารณาตัวแปรที่ p-value น้อยกว่า 0.05 ซึ่งมาจากการทดสอบว่า coefficient ต่างจาก 0 หรือไม่ (H0: β = 0) ถ้าต้องการสร้างสมการไว้ทำนาย Y ก็ใส่ X ได้หลายตัวเช่นกัน แต่เลือกโมเดลที่ fit กับข้อมูลดีที่สุด คือค่าที่ทำนายได้ใกล้กับค่าจริง เช่น ดูว่า X อธิบายความแปรปรวนของ Y ได้มากเพียงใด (0 คือไม่ fit, 1 คือ fit สมบูรณ์) ทั้งสองแบบจึงใช้ X ได้หลายตัว การสลับเกณฑ์ของสองแบบผิด และตัวแปรที่ p-value มากกว่า 0.05 ไม่ได้แสดงความสัมพันธ์ที่มีนัยสำคัญ",
