    "type": "mcq",
    "q": "แบบจำลอง multivariable logistic regression ของการเกิดลูกแรกคลอดน้ำหนักตัวน้อย ได้สมการ ln(odds) = 0.861 − 0.013(mother weight) − 0.971(white) + 0.320(black) + 1.060(smoke) เมื่อควบคุมตัวแปรอื่นในสมการแล้ว odds ratio ของการสูบบุหรี่ขณะตั้งครรภ์ (สูบเทียบกับไม่สูบ) เท่ากับเท่าใด",
    "options": [
      "0.704",
      "2.886",
      "1.060",
      "2.02"
    ],
    "answer": 1,
    "explain": "ในสมการ logistic regression ค่าที่หน้าตัวแปรแต่ละตัวเป็น coefficient ซึ่งอยู่ในรูป log(OR) OR ของการสูบบุหรี่จึงได้จากการแปลงด้วย exponential คือ e^1.060 ≈ 2.886 แปลว่า odds ของการเกิดลูกแรกคลอดน้ำหนักตัวน้อยในแม่ที่สูบบุหรี่เป็น 2.886 เท่าของแม่ที่ไม่สูบ เมื่อควบคุมน้ำหนักและเชื้อชาติของแม่แล้ว ค่า 1.060 เป็นตัว coefficient ยังไม่ใช่ OR ส่วน 2.02 และ 0.704 เป็น OR และ coefficient ของการสูบบุหรี่จากการวิเคราะห์ตัวแปรเดียว (simple logistic regression) ซึ่งยังไม่ได้ควบคุมตัวแปรอื่น",
