    "q": "ข้อใดอธิบายจุดเริ่มต้นและทิศทางของ case-control study และ cohort study ได้ถูกต้อง",
    "options": [
      "Case-control เริ่มจากสัตว์ที่ยังไม่ป่วยซึ่งแบ่งตามการสัมผัสปัจจัยแล้วติดตามไปข้างหน้า; cohort เริ่มจากสัตว์ป่วยและไม่ป่วยแล้วสืบย้อนหาปัจจัย",
      "ทั้งสองแบบเริ่มจากสัตว์ป่วยและไม่ป่วยแล้วสืบย้อนหาปัจจัยเหมือนกัน ต่างกันเพียงว่า cohort ใช้จำนวนสัตว์มากกว่าและเก็บข้อมูลนานกว่า",
      "Case-control สุ่มกำหนดให้สัตว์ได้รับหรือไม่ได้รับปัจจัยแล้วรอดูผล; cohort วัดปัจจัยและโรคพร้อมกัน ณ จุดเวลาเดียวโดยไม่ติดตามสัตว์",
      "Case-control เริ่มจากสัตว์ป่วยและไม่ป่วยแล้วสืบย้อนหาปัจจัย; cohort เริ่มจากสัตว์ที่ยังไม่ป่วยซึ่งแบ่งตามการมีปัจจัยแล้วติดตามไปข้างหน้า"
    ],
    "answer": 3,
    "explain": "case-control เลือกตัวอย่างจากผลลัพธ์ คือกลุ่มที่เป็นโรค (case) และไม่เป็นโรค (control) แล้วมองย้อนอดีตว่าแต่ละกลุ่มเคยสัมผัสปัจจัยใดบ้าง ส่วน cohort เริ่มจากสัตว์ที่ยังไม่เป็นโรค แบ่งตามสถานะการสัมผัส (มีปัจจัย A กับไม่มีปัจจัย A) ซึ่งเกิดขึ้นเองตามธรรมชาติ แล้วติดตามไปข้างหน้าเพื่อนับการเกิดโรค จึงสร้างลำดับเวลาจากการสัมผัสไปสู่ผลลัพธ์ได้ การสลับจุดเริ่มต้นของสองแบบจึงผิด การสุ่มกำหนดปัจจัยให้สัตว์เป็นลักษณะของ experimental study และการวัดปัจจัยกับโรคพร้อมกัน ณ เวลาเดียวเป็นลักษณะของ cross-sectional study",
