      "Cross-sectional study เพราะวัดการสัมผัสปัจจัยและการเป็นโรคพร้อมกันในเวลาเดียว",
      "Cohort study ที่ไม่ได้บันทึกระยะเวลาติดตามของแต่ละตัว เพราะนับจำนวนป่วยรายใหม่ได้ครบ"
