    "answer": 0,
    "explain": "incidence rate คือจำนวนป่วยรายใหม่หารด้วยผลรวมเวลาที่สัตว์แต่ละตัวอยู่ในภาวะเสี่ยง (animal-time at risk) จึงบอกความเร็วของการเกิดโรค cohort study ติดตามสัตว์ที่ยังไม่ป่วยไปข้างหน้าและรู้ว่าแต่ละตัวอยู่ในการศึกษานานเท่าใด จึงได้ animal-time และคำนวณ incidence rate ได้ ถ้าไม่ได้บันทึกเวลาของแต่ละตัวจะคำนวณได้เพียง cumulative incidence ซึ่งเป็นสัดส่วน ไม่ใช่อัตรา case-control เลือกตัวอย่างจากผลลัพธ์จึงวัด incidence โดยตรงไม่ได้ และ cross-sectional วัดการสัมผัสกับโรค ณ จุดเวลาเดียว จึงได้เพียง prevalence",
