    "explain": "survival time analysis เป็นวิธีทางสถิติที่ประมาณโอกาสที่เหตุการณ์หนึ่ง เช่น การตาย การกลับเป็นซ้ำของโรค หรือความล้มเหลว จะเกิดขึ้นภายในช่วงเวลาหนึ่ง ข้อมูลที่ใช้จึงต้องมีทั้งเหตุการณ์ (event) ที่นิยามไว้ชัดเจนและเวลาที่สัตว์แต่ละตัวถูกติดตามจนเกิดเหตุการณ์ (time) ร่วมกับปัจจัยที่สนใจ ส่วนความชุก ณ จุดเวลาไม่ได้ใช้เวลาจนเกิดเหตุการณ์ ผลต่างค่าเฉลี่ยของสองกลุ่มอิสระเป็นงานของ two sample t-test และ odds ของการสัมผัสในกลุ่มป่วยเทียบกลุ่มไม่ป่วยคือ odds ratio จาก case-control",
