    "explain": "สูตรขนาดตัวอย่างของ unmatched case-control ใช้สัดส่วนการสัมผัสปัจจัย ไม่ใช่สัดส่วนการเกิดโรค p1 คือสัดส่วนของกลุ่ม case (แมวอ้วน) ที่สัมผัสปัจจัย (ทำหมัน) เท่ากับ 0.71 และ p2 คือสัดส่วนของกลุ่ม control (แมวไม่อ้วน) ที่สัมผัสปัจจัย เท่ากับ 0.38 การอ่าน 0.38 หรือ 0.71 เป็นสัดส่วนแมวอ้วนในกลุ่มที่ทำหมันหรือไม่ทำหมันเป็นการอ่านแบบ cohort ซึ่งใช้สัดส่วนการเกิดโรคในกลุ่มสัมผัสและไม่สัมผัส และ 0.71 เป็น p1 ไม่ใช่ p2",
