    "q": "ในการวางแผน observational study สิ่งใดต้องกำหนดเป็นอันดับแรก เพราะเป็นตัวกำหนดระดับของหน่วยที่ศึกษา การวัด study design และขนาดตัวอย่างที่ตามมา",
