    "year": 5,
    "type": "mcq",
    "q": "กรมปศุสัตว์ใช้ผลการประเมินความเสี่ยงเลือกเก็บตัวอย่างเฉพาะฟาร์มสุกรที่มีระดับความปลอดภัยทางชีวภาพต่ำ เพื่อใช้ทรัพยากรที่มีอยู่อย่างคุ้มค่า การเฝ้าระวังโรคเชิงรุกนี้เป็นรูปแบบใด",
    "options": [
      "Sentinel surveillance",
      "General surveillance",
      "Targeted surveillance",
      "Passive surveillance"
    ],
    "answer": 2,
    "explain": "การเลือกเฝ้าระวังเฉพาะกลุ่มหรือพื้นที่ที่ผลการประเมินความเสี่ยงชี้ว่าเสี่ยงสูง เช่น ฟาร์มสุกรที่ความปลอดภัยทางชีวภาพต่ำซึ่งมีโอกาสเกิด ASF มากกว่า คือ targeted surveillance หรือการเฝ้าระวังตามพื้นที่เสี่ยง (risk-based surveillance) ซึ่งนำการประเมินการสัมผัสและความเสี่ยงมาใช้ร่วมกับการออกแบบแบบเดิม เพื่อกำหนดความจำเป็นของการเฝ้าระวัง จัดลำดับความสำคัญ และจัดสรรทรัพยากรให้คุ้มค่า การเฝ้าระวังเชิงรุกเมื่อแบ่งตามเป้าหมายมีสามรูปแบบ คือ general, sentinel และ targeted surveillance โดย sentinel surveillance เฝ้าดูประชากรย่อยหรือสัตว์ที่ไวต่อโรคที่เลือกไว้ เช่น นำสัตว์ที่ไม่ติดเชื้อและไม่มีภูมิคุ้มกันเข้าไปเลี้ยงในพื้นที่แล้วดูว่าป่วยหรือไม่ เพื่อให้ได้ข้อมูลทันเวลาด้วยต้นทุนต่ำ ไม่ได้มุ่งประมาณความชุกให้แม่นยำ ส่วน passive surveillance คือการรอรับรายงานจากเกษตรกรและเครือข่าย ไม่ใช่การที่หน่วยงานเลือกเข้าไปเก็บตัวอย่างเอง",
    "source": "นโยบายภาครัฐ และการป้องกัน ควบคุมและกำจัดโรคระบาดสัตว์ หน้า 36-38, 41; 12 - นโยบายภาครัฐ และการป้องกัน ควบคุมและกำจัดโรคระบาดสัตว์ deck 2024 หน้า 29",
    "verified": "สรุปและบันทึกหลังสอบปลายภาคของ Vet 85 หน้า 10 (ดาวสีชมพูที่กรอบการแบ่งการเฝ้าระวังเชิงรุกตามเป้าหมาย ตามคำอธิบายสัญลักษณ์หน้า 9 ว่าดาวคือ 85) มาร์คโดย Vet 85; สไลด์นโยบายภาครัฐและการป้องกัน ควบคุมและกำจัดโรคระบาดสัตว์ ชุดปี 2567 หน้า 29 (ไฮไลต์ General, Sentinel และ Targeted surveillance พร้อมบันทึกตัวอย่างของแต่ละแบบ) ในชุดไฟล์ของ Vet 84 (รุ่นที่มาร์คไม่ได้ระบุบนหน้า อนุมานจากโฟลเดอร์)",
