    "q": "ในการฉีดวัคซีนประจำปี (mass vaccination) ตามแผนปฏิบัติการเฝ้าระวัง ป้องกัน ควบคุมและกำจัดโรคของประเทศไทย โรคใดฉีดเฉพาะโค กระบือ แพะ และแกะ ในพื้นที่ที่มีประวัติการระบาด ปีละ 2 ครั้ง",
    "options": [
      "Blackleg",
      "Haemorrhagic septicaemia",
      "Anthrax",
      "Brucellosis"
    ],
    "answer": 0,
    "explain": "Blackleg อยู่ในกลุ่มการฉีดวัคซีนประจำปีแต่จำกัดพื้นที่ คือฉีดโค กระบือ แพะ และแกะ อายุ 4 เดือนขึ้นไป เฉพาะในพื้นที่ที่มีประวัติการระบาด ปีละ 2 ครั้ง Haemorrhagic septicaemia ก็เป็นการฉีดวัคซีนประจำปี แต่ฉีดในโคและกระบือปีละครั้งโดยไม่ได้จำกัดเฉพาะพื้นที่ที่เคยระบาด ส่วน Anthrax และ Brucellosis ไม่อยู่ในกลุ่มนี้ ทั้งสองเป็นการฉีดวัคซีนควบคุมโรค (emergency vaccination) โรคในกลุ่มการฉีดวัคซีนประจำปี ได้แก่ FMD, Haemorrhagic septicaemia, Blackleg (เฉพาะพื้นที่), Lumpy skin disease, อหิวาต์สุกร, นิวคาสเซิลและหลอดลมอักเสบติดต่อ, อหิวาต์เป็ดไก่, กาฬโรคเป็ด และโรคพิษสุนัขบ้า โดย FMD ฉีดโคนมปีละ 3 ครั้ง และฉีดโคเนื้อกับกระบือปีละ 2 ครั้ง",
    "source": "นโยบายภาครัฐ และการป้องกัน ควบคุมและกำจัดโรคระบาดสัตว์ หน้า 43-44; 12 - นโยบายภาครัฐ และการป้องกัน ควบคุมและกำจัดโรคระบาดสัตว์ deck 2024 หน้า 30-31",
    "verified": "สรุปและบันทึกหลังสอบปลายภาคของ Vet 85 หน้า 10 (ดาวสีชมพูที่บรรทัด Mass vaccination และเครื่องหมายถูกเหนือ FMD ตามคำอธิบายสัญลักษณ์หน้า 9 ว่าดาวคือ 85) มาร์คโดย Vet 85; สไลด์นโยบายภาครัฐและการป้องกัน ควบคุมและกำจัดโรคระบาดสัตว์ ชุดปี 2567 หน้า 30 (ไฮไลต์การฉีดวัคซีนประจำปีและการฉีดวัคซีนควบคุมโรค) และหน้า 31 (ไฮไลต์ตารางโปรแกรมการรณรงค์ฉีดวัคซีน กำกับ M และ E หน้าชื่อโรค และบันทึกที่ Blackleg ว่าฉีดในพื้นที่ที่มีการระบาดเท่านั้น) ในชุดไฟล์ของ Vet 84 (รุ่นที่มาร์คไม่ได้ระบุบนหน้า อนุมานจากโฟลเดอร์)",
