    "q": "ตามมาตรการการสร้างฟาร์มและพื้นที่ปลอดโรค (free farm, free zone, compartment) ประเทศไทยดำเนินการเพื่อให้ปลอดโรคปากและเท้าเปื่อยในรูปแบบใด",
    "options": [
      "รับรองฟาร์มปลอดโรคปากและเท้าเปื่อยเป็นรายฟาร์มทั่วประเทศ",
      "จัดตั้งคอมพาร์ทเมนต์ปลอดโรคปากและเท้าเปื่อยในฟาร์มโคนม",
      "ได้รับคืนสถานภาพประเทศปลอดโรคปากและเท้าเปื่อยจาก WOAH แล้ว",
      "สร้างพื้นที่ปลอดโรคปากและเท้าเปื่อยในภาคตะวันออกของประเทศ"
    ],
    "answer": 3,
    "explain": "การทำให้ฟาร์มแต่ละแห่งปลอดโรคปากและเท้าเปื่อยทำได้ยากเพราะมีการเคลื่อนย้ายสัตว์ มาตรการของไทยจึงเป็นการสร้างพื้นที่ปลอดโรค (free zone) ในภาคตะวันออก ซึ่งยังอยู่ระหว่างดำเนินการ ส่วนการรับรองเป็นรายฟาร์มใช้กับฟาร์มปลอดโรคบรูเซลลาและฟาร์มปลอดวัณโรค คอมพาร์ทเมนต์ปลอดโรคใช้กับสัตว์ปีกและสุกร และสถานภาพที่ไทยกำลังขอคืนจาก WOAH คือการปลอดโรคลัมปี สกิน ไม่ใช่โรคปากและเท้าเปื่อย นอกจากนี้ประเทศไทยปลอดกาฬโรคแอฟริกาในม้าและโรครินเดอร์เปสต์แล้ว",
    "source": "นโยบายภาครัฐ และการป้องกัน ควบคุมและกำจัดโรคระบาดสัตว์ หน้า 55; 12 - นโยบายภาครัฐ และการป้องกัน ควบคุมและกำจัดโรคระบาดสัตว์ deck 2024 หน้า 37",
    "verified": "สรุปและบันทึกหลังสอบปลายภาคของ Vet 85 หน้า 10 (ดาวสีชมพูและขีดเส้นใต้ที่ 'ฟาร์มปลอดโรค FMD (พยายามทำแต่ยาก เพราะปัญหาการเคลื่อนย้าย)' ตามคำอธิบายสัญลักษณ์หน้า 9 ว่าดาวคือ 85) มาร์คโดย Vet 85; สไลด์นโยบายภาครัฐและการป้องกัน ควบคุมและกำจัดโรคระบาดสัตว์ ชุดปี 2567 หน้า 37 (ไฮไลต์ฟาร์มปลอดโรคบรูเซลลาและวัณโรค พื้นที่ปลอดโรคปากและเท้าเปื่อยในภาคตะวันออก และการปลอดกาฬโรคแอฟริกาในม้ากับรินเดอร์เปสต์ พร้อมบันทึกว่าพื้นที่ภาคตะวันออกยังไม่สำเร็จ) ในชุดไฟล์ของ Vet 84 (รุ่นที่มาร์คไม่ได้ระบุบนหน้า อนุมานจากโฟลเดอร์)",
