    "q": "ข้อใดกล่าวถูกต้องเกี่ยวกับการฉีดวัคซีนควบคุมโรค (emergency vaccination) ตามแผนของประเทศไทย",
    "options": [
      "Brucellosis ฉีดโคเนื้อและกระบือทั้งเพศผู้และเพศเมีย อายุ 4 เดือนขึ้นไปในทุกฝูง",
      "Anthrax ฉีดโค กระบือ แพะ แกะ ในรัศมี 5 กิโลเมตรรอบจุดพบเชื้อ ต่อเนื่องอย่างน้อย 5 ปี",
      "Anthrax ฉีดประจำปีในโค กระบือ แพะ แกะ ทุกตัวทั่วประเทศ ตั้งแต่อายุ 4 เดือน",
      "Brucellosis ฉีดรอบจุดเกิดโรคเพียงครั้งเดียว แล้วหยุดเมื่อไม่พบสัตว์ป่วยรายใหม่"
    ],
    "answer": 1,
    "explain": "การฉีดวัคซีนควบคุมโรคใช้กับ Brucellosis และ Anthrax โดยฉีดเฉพาะที่ที่มีโรค แทนการฉีดประจำปีทั่วประเทศ วัคซีน Anthrax ไม่ได้ใช้ฉีดเป็นประจำมาตั้งแต่ปี 2000 แต่สำรองไว้ใช้ควบคุมโรคเมื่อเกิดการระบาด เมื่อพบเชื้อแอนแทรกซ์ในสิ่งแวดล้อม จะฉีดวัคซีนโค กระบือ แพะ แกะ ในรัศมี 5 กิโลเมตรรอบจุดที่พบเชื้อ ต่อเนื่องอย่างน้อย 5 ปี ส่วนวัคซีน Brucellosis ฉีดเฉพาะโคเนื้อและกระบือเพศเมีย อายุ 6-8 เดือนขึ้นไป ในฝูงที่มีความชุกมากกว่า 2% ปีละครั้ง การฉีดรอบจุดเกิดโรคครั้งเดียวแล้วหยุดเป็นลักษณะของการฉีดวัคซีนรอบจุดเกิดโรค (ring vaccination) ซึ่งไม่ต่อเนื่องเท่าการฉีดวัคซีนควบคุมโรค",
    "source": "นโยบายภาครัฐ และการป้องกัน ควบคุมและกำจัดโรคระบาดสัตว์ หน้า 43-44, 52; โรคแอนแทรกซ์ (Anthrax) — แผนเผชิญเหตุ หน้า 24",
