    "explain": "มาตรา 4 นิยามโรคระบาดโดยระบุชื่อโรคไว้ เช่น กาฬโรคเป็ด โรคไข้หวัดนก โรคบรูเซลลา โรคปากและเท้าเปื่อย โรคพิษสุนัขบ้า โรคแอนแทรกซ์ โรคเฮโมรายิกเซปทิซีเมีย และวัณโรค แล้วปิดท้ายด้วยโรคอื่นตามที่รัฐมนตรีประกาศกำหนด ซึ่งเป็นช่องทางสำหรับโรคที่จะประกาศเพิ่มในภายหลัง รายชื่อของไทยอิงโรคในรายชื่อของ WOAH ร่วมกับโรคที่ระบาดในประเทศ แต่โรคจะเป็นโรคระบาดตามกฎหมายได้เมื่อระบุไว้ในมาตรา 4 หรือรัฐมนตรีประกาศกำหนด ส่วนผู้ว่าราชการจังหวัดมีอำนาจประกาศเขตโรคระบาดหรือเขตเฝ้าระวังโรคระบาดตามมาตรา 21 ซึ่งเป็นการประกาศพื้นที่ ไม่ใช่การกำหนดชื่อโรค",
