    "year": 5,
    "type": "mcq",
    "q": "การเฝ้าระวังโรคระบาดสัตว์ทางอาการ (clinical surveillance) ต้องอาศัยนิยามทางอาการ (case definition) ที่ชัดเจน ข้อใดกล่าวถูกต้องเกี่ยวกับการใช้นิยามนี้ตลอดช่วงการระบาด",
    "options": [
      "ช่วงแรกของการระบาดเน้นความจำเพาะ แล้วเพิ่มความไวในช่วงหลัง เพื่อไม่ให้พลาดผู้ป่วยรายท้าย ๆ",
      "ใช้นิยามเดียวกันตลอดการระบาด เพราะการปรับนิยามทำให้นับจำนวนผู้ป่วยเทียบกันไม่ได้",
      "นับเฉพาะรายที่ยืนยันทางห้องปฏิบัติการตั้งแต่ต้น เพื่อให้ความจำเพาะสูงตลอดการระบาด",
      "ช่วงแรกของการระบาดเน้นความไว แล้วเพิ่มความจำเพาะในช่วงหลัง โดยปรับตามสถานการณ์ของโรค"
    ],
    "answer": 3,
    "explain": "ช่วงแรกของการระบาด นิยามทางอาการต้องไวพอที่จะไม่พลาดสัตว์ที่อาจป่วย เช่น ช่วงแรกของกาฬโรคแอฟริกาในม้า พบม้าตายก็นับเป็นผู้ป่วย หรือโรคลัมปี สกิน พบตุ่มก็นับ เมื่อรู้จักโรคมากขึ้นจึงเพิ่มความจำเพาะเพื่อตัดรายที่ไม่ใช่โรคออก นิยามจึงปรับได้ตามสถานการณ์ของโรค และสุดท้ายยืนยันด้วยผลห้องปฏิบัติการ การเปลี่ยนนิยามอาจทำให้จำนวนผู้ป่วยดูเพิ่มขึ้นทั้งที่ไม่ได้ระบาดมากขึ้นจริง จึงต้องรู้ว่านิยามเปลี่ยนเมื่อใด แต่ไม่ได้แปลว่าต้องใช้นิยามเดียวตลอด ส่วนการนับเฉพาะรายยืนยันตั้งแต่ต้นคือการเน้นความจำเพาะตั้งแต่ช่วงแรก ซึ่งตรงข้ามกับหลักที่ช่วงแรกต้องเน้นความไว",
    "source": "2. Outbreak investigation SJ 2026 หน้า 17, 20; 12 - นโยบายภาครัฐ และการป้องกัน ควบคุมและกำจัดโรคระบาดสัตว์ deck 2024 หน้า 27-28",
