    "explain": "การควบคุมเคลื่อนย้ายสัตว์แบ่งเป็นสามระดับ ระหว่างประเทศใช้ health requirement ร่วมกับ health certification คือประเทศนำเข้ากำหนดเงื่อนไขด้านสุขภาพจากการวิเคราะห์ความเสี่ยง และประเทศส่งออกออกใบรับรองสุขภาพ บริเวณชายแดนใช้ health requirement ร่วมกับข้อตกลงทวิภาคี (bilateral agreement) และอีกระดับคือการควบคุมเคลื่อนย้ายสัตว์ภายในประเทศ การประเมินความเสี่ยงเป็นฐานของการกำหนดเงื่อนไข เช่น การประเมินความเสี่ยงเชิงคุณภาพของการนำเชื้อไวรัสปากและเท้าเปื่อยซีโรไทป์ SAT2 เข้าประเทศผ่านการนำเข้าสัตว์เคี้ยวเอื้องจากเมียนมาทางด่านกักกันสัตว์ชายแดน 10 แห่ง",
