    "explain": "Bloom's taxonomy มี 6 ระดับ เรียงจากต่ำไปสูง คือ Remember จำได้ (recognizing and recalling facts), Understand เข้าใจ (understanding what the facts mean), Apply นำไปใช้ได้ (applying the facts, rules, concepts and ideas), Analyze วิเคราะห์ได้ (breaking down information into component parts), Evaluate ประเมินได้ (judging the value of information or ideas) และ Create สร้างสรรค์ได้ (combining parts to make a new whole) Analyze คือการแยกข้อมูลออกเป็นส่วนประกอบย่อย ส่วน Evaluate คือการตัดสินคุณค่าของข้อมูลหรือความคิด ซึ่งอยู่สูงกว่า Analyze หนึ่งระดับ",
