    "q": "แผนปฏิบัติการควบคุม ป้องกันและกำจัดโรคปากและเท้าเปื่อยของประเทศไทยครอบคลุมช่วงปีใด และตั้งเป้าลดอุบัติการณ์การระบาดของโรคในโคนม โคเนื้อ กระบือ แพะและแกะไว้เท่าใด",
