    "answer": 2,
    "explain": "แผนเริ่มจากผู้ทรงคุณวุฒิวิเคราะห์ผู้มีส่วนได้ส่วนเสีย (stakeholder analysis) ทั้งตามห่วงโซ่อุปทานและตามมาตรการ เพื่อระบุให้ครบว่าใครบ้างที่ประกอบอาชีพเกี่ยวข้อง จากนั้นผู้มีส่วนได้ส่วนเสียให้ความคิดเห็นเรื่องเป้าหมายของแผนในระยะเร่งด่วนและระยะยาว จุดอ่อนจุดแข็ง และประสิทธิผล ความพร้อม และผลกระทบของมาตรการต่าง ๆ แล้วจึงประชุมเชิงปฏิบัติการเกี่ยวกับมาตรการเฝ้าระวัง ควบคุม และป้องกัน ได้เป็นร่างแผน ก่อนนำร่างมาสรุปเป็นแผนปฏิบัติการ การวิเคราะห์ผู้มีส่วนได้ส่วนเสียต้องมาก่อน เพราะต้องรู้ก่อนว่าใครคือผู้ที่จะให้ความคิดเห็นและเข้าประชุม และการให้ความคิดเห็นมาก่อนการประชุมเชิงปฏิบัติการที่ทำมาตรการออกมาเป็นร่างแผน ตลอดกระบวนการทุกฝ่ายต้องเห็นตรงกันโดยหาจุดสมดุล เช่น เกษตรกรอาจอยากให้ปลอดโรคภายใน 1 ปีซึ่งทำไม่ได้จริง และต้องหาว่าต้องทำอะไรจึงจะถึงเป้าหมาย ซึ่งคำตอบหลักคือการฉีดวัคซีน",
