    "answer": 0,
    "explain": "เชื้อไวรัสลัมปี สกินที่พบในประเทศไทยช่วงแรกของการระบาดเป็นสายพันธุ์ลูกผสม และเหมือนกับเชื้อที่พบในประเทศเวียดนามมากที่สุด ไม่ใช่สายพันธุ์ที่ไม่ใช่ลูกผสม และไม่ได้ใกล้เคียงกับเชื้อจากเมียนมาที่สุด แม้ประเทศไทยนำเข้าโคจากเมียนมา ข้อมูลนี้ได้จากการสอบสวนโรคในระดับโมเลกุล ซึ่งช่วยค้นหาและสอบสวนที่มาของเชื้อได้ หลังทำวัคซีนปูพรมทั้งประเทศ เชื้อมีการกลายพันธุ์น้อยกว่าร้อยละสอง การเฝ้าระวังลักษณะทางพันธุกรรมจึงใช้ตรวจการกลายพันธุ์ด้วย ในต่างประเทศพบการกลายพันธุ์หลังการฉีดวัคซีน โดยเฉพาะประเทศที่ใช้วัคซีน sheep pox หรือ goat pox ประเทศไทยไม่ได้ใช้วัคซีนกลุ่มนี้ แต่ก็ยังพบการกลายพันธุ์บ้างในระดับน้อยมาก",
    "source": "16 - แผนปฏิบัติการ-lumpy-skin deck 2024 หน้า 20, 5",
