    "q": "แบบจำลองการระบาดและการควบคุมโรคลัมปี สกินในโคเนื้อในประเทศไทยประเมินว่า ในพื้นที่ที่โคเนื้อเคยเกิดโรคมาแล้วอย่างน้อยร้อยละ 75 ต้องทำให้ประชากรโคเนื้อภายในฝูงมีภูมิคุ้มกันหมู่อย่างน้อยร้อยละเท่าใดจึงควบคุมโรคได้",
