    "explain": "แบบจำลองประเมินว่าโคเนื้อป่วย 1 ตัวแพร่โรคไปยังโคเนื้อได้อีกประมาณ 9 ตัว ค่านี้คือค่าการแพร่เชื้อพื้นฐาน (R0) หรือจำนวนตัวที่สัตว์ป่วย 1 ตัวแพร่เชื้อต่อได้ และแต่ละพื้นที่ไม่เท่ากัน ใน 49 อำเภอที่ศึกษามีค่าตั้งแต่ 3.29 ถึง 19.02 ด้านการสร้างภูมิคุ้มกันเพื่อควบคุมโรค พื้นที่ที่โคเนื้อเคยเกิดโรคมาแล้วอย่างน้อยร้อยละ 75 ต้องทำให้ภูมิคุ้มกันหมู่ในฝูงถึงอย่างน้อยร้อยละ 76.48 ส่วนพื้นที่ที่เคยพบโคเนื้อสัมผัสโรคมาแล้วอย่างน้อยร้อยละ 90 ระดับภูมิคุ้มกันภายในฝูงเพียงร้อยละ 62.82 ก็เพียงพอ โคที่เคยเป็นโรคมีภูมิคุ้มกันอยู่นาน ในพื้นที่ที่เกิดโรคมากเช่นนี้การสร้างภูมิคุ้มกันจึงเน้นเฉพาะลูกโคก็พอ ร้อยละ 75 และร้อยละ 90 เป็นสัดส่วนของโคที่เคยเกิดโรคหรือเคยสัมผัสโรค ไม่ใช่ระดับภูมิคุ้มกันที่ต้องการ",
    "source": "16 - แผนปฏิบัติการ-lumpy-skin deck 2024 หน้า 25",
