    "explain": "เงื่อนไขของ WOAH แยกตามการดำเนินมาตรการทำลายสัตว์ป่วย ถ้ามีการทำลายสัตว์ป่วย ต้องผ่านไป 14 เดือนหลังนำสัตว์ตัวสุดท้ายเข้าฆ่าหรือทำลาย หรือหลังใช้วัคซีนฉุกเฉินครั้งสุดท้าย โดยเฝ้าระวังทั้งทางอาการและทางห้องปฏิบัติการแล้วไม่พบการติดเชื้อ หรือ 26 เดือนถ้าเฝ้าระวังทางอาการอย่างเดียว ถ้าไม่ดำเนินมาตรการทำลายสัตว์ป่วย ต้องไม่อนุญาตให้ใช้วัคซีนอย่างน้อย 3 ปีเมื่อเฝ้าระวังทางอาการอย่างเดียว หรืออย่างน้อย 2 ปีเมื่อเฝ้าระวังทั้งทางอาการและทางห้องปฏิบัติการ โดยไม่พบการติดเชื้อ ตาม article 11.9.3 และ 11.9.15 roadmap ของแผนจึงต้องอิงเงื่อนไขนี้ หลังไม่มีการระบาดในประเทศแล้วจึงหยุดฉีดวัคซีน 2 ปี พร้อมเฝ้าระวัง แล้วยื่นขอสถานภาพกับ WOAH",
    "source": "16 - แผนปฏิบัติการ-lumpy-skin deck 2024 หน้า 26-27",
    "verified": "สไลด์แผนปฏิบัติการการเฝ้าระวัง ป้องกันและควบคุมโรคลัมปี สกินเชิงบูรณาการ ชุดปี 2567 หน้า 26 (ขีดเส้นใต้กรณีมีมาตรการทำลายสัตว์ป่วยและช่วงการเฝ้าระวังทางอาการและทางห้องปฏิบัติการ วงกลมคำว่าไม่ในกรณีไม่ดำเนินมาตรการทำลายสัตว์ป่วย บันทึกลายมือว่าหยุดวัคซีนอย่างน้อย 2 ปี และไฮไลต์บันทึกว่าการกำหนด roadmap ต้องอิง WOAH) ในชุดไฟล์ของ Vet 84 (รุ่นที่มาร์คไม่ได้ระบุบนหน้า อนุมานจากโฟลเดอร์)",
