    "explain": "PPP ไม่ใช่การที่ฝ่ายใดฝ่ายหนึ่งทำงานแทนอีกฝ่าย ทุกภาคส่วนรับผิดชอบงานร่วมกัน นำทรัพยากรมาใช้ร่วมกัน และรับความเสี่ยงร่วมกัน เป้าหมายจึงเป็นประโยชน์ที่ทุกฝ่ายได้ร่วมกันอย่างยั่งยืน ไม่ใช่ประโยชน์ของฝ่ายเดียว ผลที่ตามมา เช่น เศรษฐกิจประเทศดีขึ้น ความไว้วางใจของผู้เกี่ยวข้อง ลดความเสี่ยงและเพิ่มโอกาส การพัฒนาระบบสาธารณสุข และสังคมที่ดีขึ้น เป็นประโยชน์ของ PPP ไม่ใช่ตัววัตถุประสงค์",
